window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[27]={"id":"027","numero":27,"titre":"Prévention risques fœtaux","objectifs":[{"id":"27-1","rang":"B","rubrique":"Définition","titre":"Connaître la définition de l'infection materno-fœtale (IMF)","contenu":"<p>L'<span class=\"kw-def\">infection materno-fœtale (IMF)</span> est une infection contractée par le fœtus ou le nouveau-né à partir de germes d'origine maternelle, transmise au cours de la <span class=\"kw-ci\">grossesse</span>, à l'accouchement ou en post-partum immédiat.</p>\n      <table >\n        <thead><tr><th>Période</th><th>Mode</th><th>Conséquences possibles</th></tr></thead>\n        <tbody>\n          <tr><td>Anténatale</td><td>Passage transplacentaire hématogène</td><td><span class=\"kw-alerte\">Embryopathie</span>, fœtopathie, <span class=\"kw-alerte\">MFIU</span>, fausse couche</td></tr>\n          <tr><td>Per-partum</td><td>Voie ascendante (filière génitale) ou contact direct</td><td>Chorioamniotite, accouchement prématuré, infection néonatale précoce</td></tr>\n          <tr><td>Post-natale</td><td><span class=\"kw-ci\">Allaitement</span>, contact</td><td>Infection néonatale tardive (symptomatique d'emblée ou à distance)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Fréquence :</strong> <span class=\"kw-chiffre\">1 à 4 %</span> des naissances toutes infections confondues, <span class=\"kw-chiffre\">2 à 4 ×</span> plus chez les prématurés.</div>\n      <p>Toute infection fébrile chez la femme enceinte peut, de façon non spécifique, être responsable d'une <span class=\"kw-alerte\">fausse couche spontanée</span>, même sans atteinte directe du tissu embryonnaire.</p>","frequence":0},{"id":"27-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie \"microbienne\" des IMF","contenu":"<p>Les germes responsables d'IMF se répartissent en <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>randes familles. Le profil microbien dépend de la voie de contamination.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Germes principaux</th><th>Voie dominante</th></tr></thead>\n        <tbody>\n          <tr><td>Bactéries</td><td><span class=\"kw-etio\">Listeria monocytogenes</span>, <span class=\"kw-etio\">Streptococcus agalactiae</span> (SGB), <span class=\"kw-etio\">Escherichia coli</span>, <span class=\"kw-etio\">syphilis</span>, <span class=\"kw-def\">tuberculose</span>, <span class=\"kw-clinique\">fièvre</span> Q</td><td>Hématogène (<span class=\"kw-etio\">Listeria</span>) · ascendante (SGB, <span class=\"kw-etio\">E. coli</span>) · transplacentaire (<span class=\"kw-etio\">syphilis</span>)</td></tr>\n          <tr><td>Parasites</td><td><span class=\"kw-etio\">Toxoplasma gondii</span>, paludisme</td><td>Hématogène transplacentaire</td></tr>\n          <tr><td>Virus</td><td><span class=\"kw-etio\">Grippe</span>, <span class=\"kw-def\">hépatite</span> B, <span class=\"kw-etio\">HSV</span>, varicelle, rubéole, CMV, VIH, parvovirus B19, Zika</td><td>Hématogène (rubéole, <span class=\"kw-etio\">CMV</span>, parvo, toxo, VIH) · per-partum (HSV, VHB, VIH)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span> · 162 — IST · 167 — Hépatites virales · 168 — Herpesvirus · 169 — <span class=\"kw-etio\">VIH</span> · 170 — Paludisme · 173 — Zoonose</em></p>","frequence":2},{"id":"27-3","rang":"A","rubrique":"Physiopathologie","titre":"**Connaître les principaux mécanismes des IMF**","contenu":"<p>Trois voies de contamination structurent la <span class=\"kw-def\">physiopathologie</span> des IMF — le piège QCM est de relier la voie au germe et à la conséquence attendue.</p>\n      <table >\n        <thead><tr><th>Voie</th><th>Mécanisme</th><th>Germes typiques</th><th>Conséquences ⚠️</th></tr></thead>\n        <tbody>\n          <tr><td>Hématogène transplacentaire</td><td>Bactériémie/virémie maternelle → passage placentaire</td><td><span class=\"kw-etio\">Listeria</span>, <span class=\"kw-etio\">CMV</span>, rubéole, toxo, parvovirus B19, <span class=\"kw-etio\">syphilis</span></td><td><span class=\"kw-alerte\">Atteinte fœtale</span> (embryo/fœtopathie)</td></tr>\n          <tr><td>Ascendante cervico-vaginale</td><td>Germes de la filière génitale → membranes</td><td>SGB, <span class=\"kw-etio\">E. coli</span>, <span class=\"kw-etio\">vaginose</span></td><td><span class=\"kw-alerte\">MAP</span>, chorioamniotite, fausse couche tardive</td></tr>\n          <tr><td>Per-partum / post-natale</td><td>Contact filière génitale ou <span class=\"kw-ci\">allaitement</span></td><td>SGB, <span class=\"kw-etio\">HSV</span>, VHB, VIH, CMV</td><td>Infection néonatale précoce ou tardive</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège QCM :</strong> distinguer la <span class=\"kw-clinique\">fenêtre embryonnaire</span> (<span class=\"kw-chiffre\">J0</span>–J56, organogenèse, malformations structurelles) de la <span class=\"kw-clinique\">fenêtre fœtale</span> (> J56, atteinte fonctionnelle et croissance). L'évocation devant un point d'appel maternel (<span class=\"kw-clinique\">fièvre</span>) <em>ou</em> fœtal (signe échographique, altération du bien-être) est obligatoire.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span> · 162 — IST</em></p>","frequence":2},{"id":"27-4","rang":"A","rubrique":"Définition","titre":"Toxoplasmose : connaître les conséquences de l'IMF","contenu":"<p>La toxoplasmose <span class=\"kw-etio\">congénitale</span> résulte de la <span class=\"kw-def\">primo-infection maternelle</span> pendant la <span class=\"kw-ci\">grossesse</span> (<span class=\"kw-chiffre\">1-2 %</span> des grossesses, 4000-5000 femmes/an en France).</p>\n      <table >\n        <thead><tr><th>Période</th><th>Risque transmission</th><th>Sévérité fœtale</th></tr></thead>\n        <tbody>\n          <tr><td>Périconceptionnelle (0-7 SA)</td><td><span class=\"kw-chiffre\">1 %</span></td><td>Embryopathie/fœtopathie sévère <span class=\"kw-chiffre\">60 %</span> (avortement, MFIU)</td></tr>\n          <tr><td>Jusqu'à 13 SA</td><td><span class=\"kw-chiffre\">5 %</span></td><td>Lésions sévères</td></tr>\n          <tr><td>2ᵉ trimestre</td><td><span class=\"kw-chiffre\">40 %</span></td><td>Fœtopathie ou forme infraclinique <span class=\"kw-chiffre\">25 %</span></td></tr>\n          <tr><td>3ᵉ trimestre</td><td><span class=\"kw-chiffre\">70 %</span></td><td>Formes sérologiques pures ou choriorétinite <span class=\"kw-chiffre\">9 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Manifestations chez l'enfant contaminé :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Atteinte infraclinique</span> :<span class=\"kw-chiffre\"> 70 %</span></li>\n        <li><span class=\"kw-clinique\">Forme légère</span> :<span class=\"kw-chiffre\"> 25 %</span></li>\n        <li><span class=\"kw-clinique\">Forme grave</span> (< 5 %) : <span class=\"kw-alerte\">microcéphalie</span>, <span class=\"kw-alerte\">hydrocéphalie</span>, <span class=\"kw-alerte\">calcifications intracrâniennes</span>, <span class=\"kw-alerte\">choriorétinite</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Paradoxe à retenir :</strong> le risque de transmission augmente avec le terme, mais la sévérité décroît — l'infection T1 est rare mais dévastatrice, l'infection T3 est fréquente mais souvent infraclinique.</div>","frequence":0},{"id":"27-5","rang":"A","rubrique":"Prise en charge","titre":"Toxoplasmose : connaître les modalités de surveillance d'une femme enceinte séronégative pour la toxoplasmose","contenu":"<p>La <span class=\"kw-bio\">sérologie toxoplasmose</span> est <strong>obligatoire au 1ᵉʳ trimestre</strong> (1ʳᵉ consultation) chez toute femme enceinte. <span class=\"kw-chiffre\">45-50 %</span> des femmes enceintes en France sont séronégatives.</p>\n      <table >\n        <thead><tr><th>Statut</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td>Femme immune (IgG+)</td><td>Aucune <span class=\"kw-def\">surveillance</span>, aucune précaution</td></tr>\n          <tr><td>Femme non-immune</td><td><strong><span class=\"kw-def\">Prévention primaire</span></strong> (conseils alimentaires/chats — voir obj-5) + <strong><span class=\"kw-def\">prévention secondaire</span> obligatoire</strong> : <span class=\"kw-bio\">sérologie mensuelle</span> (IgM, IgG) jusqu'à 3 sem après l'accouchement</td></tr>\n        </tbody>\n      </table>\n      <p><strong>CAT en cas de séroconversion :</strong></p>\n      <ul>\n        <li>Orientation <span class=\"kw-clinique\">CPDPN</span> (Centre Pluridisciplinaire de Diagnostic Prénatal)</li>\n        <li>Traitement précoce par <span class=\"kw-ttt\">spiramycine</span> <span class=\"kw-chiffre\">9 MUI/j</span> (prophylactique, diminue le risque de transmission, bien toléré)</li>\n        <li><span class=\"kw-imagerie\">PCR sur amniocentèse</span> à partir de <span class=\"kw-chiffre\">≥ 16</span>-18 SA, réalisée ≥ <span class=\"kw-chiffre\">4 semaines</span> après la date d'infection maternelle</li>\n        <li>Si <span class=\"kw-bio\">PCR</span> + : relais par <span class=\"kw-ttt\">pyriméthamine + sulfadiazine + acide folinique</span> jusqu'à l'accouchement</li>\n        <li>Échographies <span class=\"kw-imagerie\">mensuelles</span> ciblées (recherche dilatation ventriculaire, hydrocéphalie, calcifications intra-crâniennes)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Pas de vaccin :</strong> il n'existe pas de vaccin contre la toxoplasmose.</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/27/serologie-toxoplasmose-interpretation.png\" alt=\"Algorithme HAS d'interprétation d'une sérologie toxoplasmose positive chez la femme enceinte selon les profils IgG/IgM et l'indice d'avidité\" loading=\"lazy\">\n        <figcaption>Interprétation d'une <span class=\"kw-bio\">sérologie</span> toxoplasmose positive (rang C) — décision selon IgG, IgM et indice d'avidité IgG. Source : fiche source EDN item 27 — Infections et <span class=\"kw-ci\">grossesse</span>.</figcaption>\n      </figure>","frequence":0},{"id":"27-6","rang":"A","rubrique":"Prise en charge","titre":"**Toxoplasmose : connaître les principaux conseils de prévention de la toxoplasmose**","contenu":"<p>Chez la femme enceinte <strong>séronégative</strong>, les conseils de <span class=\"kw-def\">prévention primaire</span> sont remis par écrit dès le 1ᵉʳ trimestre.</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Viande bien cuite</span> (<span class=\"kw-chiffre\">≥ 67-72 °C</span> à cœur) ou congelée (-<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>18</span> °C</span>) ; éviter charcuterie crue (jambon cru, saucisson, viande fumée)</li>\n        <li><span class=\"kw-clinique\">Laver soigneusement</span> fruits, légumes, herbes aromatiques (terre potentiellement contaminée)</li>\n        <li>Éviter le <span class=\"kw-clinique\">contact avec la litière des chats</span> ; si inévitable : <span class=\"kw-clinique\">port de gants</span> + désinfection à l'eau bouillante quotidienne</li>\n        <li><span class=\"kw-clinique\">Lavage des mains</span> systématique après jardinage, manipulation de terre, manipulation de viande crue</li>\n        <li>Éviter coquillages crus, surimi, tarama</li>\n        <li>Conserver aliments crus séparés des aliments cuits/prêts à consommer</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-ttt\">Activité physique adaptée</span> :</strong><span class=\"kw-chiffre\"> 30 min</span>, 3 à 5 ×/semaine — recommandation HAS.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 24 — Complications de la grossesse · 173 — Zoonose</em></p>","frequence":2},{"id":"27-7","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les conséquences d'une rubéole au cours de la grossesse","contenu":"<p>La rubéole maternelle est <strong>grave</strong> chez la femme enceinte non immunisée — le virus est <span class=\"kw-alerte\">tératogène</span>. <span class=\"kw-chiffre\">5-10 %</span> des femmes enceintes ne sont pas immunisées en France (< 40 cas/an).</p>\n      <table >\n        <thead><tr><th>Âge gestationnel</th><th>Risque de malformation</th></tr></thead>\n        <tbody>\n          <tr><td>0-8 SA</td><td><span class=\"kw-chiffre\">85 %</span></td></tr>\n          <tr><td>9-12 SA</td><td><span class=\"kw-chiffre\">52 %</span></td></tr>\n          <tr><td>13-20 SA</td><td><span class=\"kw-chiffre\">16 %</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">> 20</span> SA</td><td><span class=\"kw-chiffre\">0 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>2 tableaux cliniques (rubéole <span class=\"kw-etio\">congénitale</span>) :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Syndrome malformatif (triade de Gregg)</span> : <span class=\"kw-alerte\">RCIU</span>, MFIU, FCS ; atteinte neurosensorielle (<span class=\"kw-alerte\">surdité</span>, microcéphalie, retard psychomoteur) ; atteinte cardiaque (<span class=\"kw-alerte\">CIV, CIA, PCA</span>, sténose artère pulmonaire) ; atteinte oculaire (<span class=\"kw-alerte\">cataracte</span>, microphtalmie, rétinopathie pigmentaire, glaucome)</li>\n        <li><span class=\"kw-clinique\">Rubéole congénitale évolutive</span> : infection chronique persistante (nouveau-né très contagieux) — RCIU, <span class=\"kw-def\">purpura</span> thrombopénique, <span class=\"kw-clinique\">hépatosplénomégalie</span>, <span class=\"kw-clinique\">ictère</span>, <span class=\"kw-clinique\">convulsions</span>, anomalies osseuses radiologiques ; <span class=\"kw-def\">pronostic</span> psychomoteur réservé</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 164 — Exanthème fébrile de l'enfant · 165 — Oreillons</em></p>","frequence":0},{"id":"27-8","rang":"A","rubrique":"Prise en charge","titre":"**Rubéole : connaître les éléments de la prévention fœtale**","contenu":"<p>La prévention de la rubéole <span class=\"kw-etio\">congénitale</span> repose sur deux axes complémentaires — primaire (vaccination) et secondaire (<span class=\"kw-def\">dépistage</span> sérologique).</p>\n      <table >\n        <thead><tr><th>Type</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Prévention primaire</span></strong></td><td><span class=\"kw-ttt\">Vaccination ROR</span> des femmes non immunisées <strong>en âge de procréer</strong> ; vaccination des enfants (calendrier vaccinal) ; femme enceinte séronégative vaccinée en <strong>post-partum</strong> (vaccin vivant atténué <span class=\"kw-ci\">CI pendant la grossesse</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Prévention secondaire</span></strong></td><td><span class=\"kw-bio\">Sérologie IgG</span> obligatoire à la 1ʳᵉ consultation (sauf immunité antérieure documentée) ; si négative : contrôle <strong>mensuel jusqu'à 18-20 SA</strong> (au-delà, risque très faible)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>CAT séroconversion T1 :</strong> avis CPDPN — <span class=\"kw-alerte\">autorisation d'IMG possible</span> si demande du couple. Si refus IMG : diagnostic anténatal par <span class=\"kw-imagerie\">amniocentèse</span> (<span class=\"kw-chiffre\">≥ 18</span> SA et ≥ 4 sem après séroconversion) + <span class=\"kw-def\">surveillance</span> échographique mensuelle. <strong>Pas de traitement curatif disponible.</strong></div>\n      <p>Délai de contraception après vaccin ROR : <span class=\"kw-chiffre\">≥ 1 mois</span> (vaccin vivant).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 164 — Exanthème fébrile de l'enfant · 165 — Oreillons</em></p>","frequence":1},{"id":"27-9","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la rougeole materno-fœtale","contenu":"<p>La <span class=\"kw-def\">rougeole materno-fœtale</span> désigne l'infection rougeoleuse contractée par la femme enceinte avec possible transmission au fœtus ou au nouveau-né. La rougeole est rare pendant la <span class=\"kw-ci\">grossesse</span> mais grave.</p>\n      <table >\n        <thead><tr><th>Mode</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Transmission placentaire</td><td>Passage hématogène transplacentaire</td></tr>\n          <tr><td>Transmission néonatale précoce</td><td>Voie aérienne en per-partum / post-natal immédiat</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Pas d'effet <span class=\"kw-ci\">tératogène</span> :</strong> contrairement à la rubéole, la rougeole <span class=\"kw-alerte\">n'est pas associée à un syndrome polymalformatif</span>. Le risque est obstétrical (FCS, prématurité) et néonatal (rougeole <span class=\"kw-etio\">congénitale</span>).</div>","frequence":0},{"id":"27-10","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les conséquences d'une rougeole au cours de la grossesse","contenu":"<table >\n        <thead><tr><th>Versant</th><th>Conséquences</th></tr></thead>\n        <tbody>\n          <tr><td>Rougeole maternelle</td><td><span class=\"kw-alerte\">Pneumonie</span> par surinfection <span class=\"kw-etio\">bactérienne</span> (forme + grave durant la <span class=\"kw-ci\">grossesse</span>) ; <span class=\"kw-alerte\">fausse couche</span>, <span class=\"kw-alerte\">prématurité</span> (comme tout syndrome fébrile)</td></tr>\n          <tr><td>Rougeole <span class=\"kw-etio\">congénitale</span> ou périnatale</td><td>Risque maximal si <span class=\"kw-clinique\">éruption</span> maternelle dans les <strong>< 10 jours précédant l'accouchement</strong> ; <span class=\"kw-clinique\">éruption</span> néonatale dans les 10 premiers jours de vie ; <span class=\"kw-def\">mortalité</span> néonatale historiquement élevée ; risque accru de <span class=\"kw-alerte\">panencéphalite subaiguë sclérosante (Van Bogaert)</span> précoce (< 2 ans) et fulminante ⚠️</td></tr>\n          <tr><td>Rougeole post-natale</td><td><span class=\"kw-clinique\">Éruption</span> entre J14 et J30 post-natal ; plus rare, généralement moins grave</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Pas de malformation <span class=\"kw-etio\">congénitale</span> :</strong> absence d'effet <span class=\"kw-ci\">tératogène</span> — le <span class=\"kw-def\">pronostic</span> est dominé par le risque maternel (pneumopathie) et néonatal (rougeole congénitale).</div>","frequence":0},{"id":"27-11","rang":"A","rubrique":"Prise en charge","titre":"Rougeole : Connaître les éléments de prévention fœtale","contenu":"<ul>\n        <li><strong><span class=\"kw-def\">Prévention primaire</span></strong> : amélioration de la <span class=\"kw-ttt\">couverture vaccinale ROR</span> avant <span class=\"kw-ci\">grossesse</span> (vaccin vivant atténué, <span class=\"kw-ci\">CI pendant la grossesse</span>) — couverture actuelle insuffisante pour éradiquer le virus</li>\n        <li><strong>CAT en cas de contage chez femme enceinte non immune</strong> : <span class=\"kw-ttt\">immunoglobulines polyvalentes IV</span>, efficaces dans les <strong><span class=\"kw-chiffre\">6 jours</span> suivant le contage</strong></li>\n        <li><strong>Si <span class=\"kw-clinique\">éruption</span> maternelle &lt; 10 j avant accouchement</strong> : Ig polyvalentes IV chez le nouveau-né <strong>dès la naissance</strong> (prévention de la rougeole <span class=\"kw-etio\">congénitale</span> et de ses complications)</li>\n        <li><strong>Inutile</strong> si <span class=\"kw-clinique\">éruption</span> maternelle &gt; 10 j avant accouchement (collège de gynéco)</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 164 — Exanthème fébrile de l'enfant · 165 — Oreillons</em></p>","frequence":0},{"id":"27-12","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l'infection à Cytomégalovirus (CMV) materno-fœtale","contenu":"<p>Le <span class=\"kw-def\">Cytomégalovirus</span> (Herpesviridae) est responsable de l'<strong>infection <span class=\"kw-etio\">virale</span> materno-fœtale la plus fréquente</strong>. Transmission hématogène transplacentaire dans les primo-infections maternelles (asymptomatiques dans <span class=\"kw-chiffre\">90 %</span> des cas).</p>\n      <table >\n        <thead><tr><th>Indicateur</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td>Femmes en âge de procréer séronégatives</td><td><span class=\"kw-chiffre\">50 %</span></td></tr>\n          <tr><td>Séroconversion pendant la <span class=\"kw-ci\">grossesse</span></td><td><span class=\"kw-chiffre\">0,5-1 %</span></td></tr>\n          <tr><td>Risque de transmission au fœtus (en moyenne)</td><td><span class=\"kw-chiffre\">40 %</span> (T1 <span class=\"kw-chiffre\">36 %</span>, T2 <span class=\"kw-chiffre\">40 %</span>, T3 <span class=\"kw-chiffre\">65 %</span>)</td></tr>\n          <tr><td>Séquelles neurodéveloppementales chez enfants infectés</td><td><span class=\"kw-chiffre\">15-20 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>1ʳᵉ cause non <span class=\"kw-etio\">héréditaire</span> de surdité neurosensorielle.</strong> Risque d'atteinte neurosensorielle uniquement si infection préconceptionnelle ou <span class=\"kw-chiffre\">≤ 12</span> SA.</div>\n      <p>Conséquences chez l'enfant contaminé : <span class=\"kw-chiffre\">80 %</span> forme asymptomatique · <span class=\"kw-chiffre\">10 %</span> apparence saine mais séquelles à distance · <span class=\"kw-chiffre\">10 %</span> infection prénatale sévère (<span class=\"kw-alerte\">RCIU, MFIU</span>, maladie des inclusions cytomégaliques : <span class=\"kw-clinique\">hépatosplénomégalie</span>, <span class=\"kw-clinique\">ictère</span>, <span class=\"kw-def\">purpura</span> thrombopénique, microcéphalie, hydrocéphalie, calcifications intracrâniennes, choriorétinite).</p>\n      <p><strong>Pas de vaccin disponible.</strong> Prévention par mesures d'hygiène +++ chez femmes au contact d'enfants &lt;<span class=\"kw-chiffre\"> 3 ans</span> (crèche, professionnels petite enfance) : ne pas partager couverts/tétines, ne pas finir les repas, lavage des mains après changes, éviter contact intime avec salive/larmes.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 168 — Herpesvirus</em></p>","frequence":0},{"id":"27-13","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes de transmission materno-fœtale des virus les plus fréquemment impliqués","contenu":"<p>Le mécanisme de transmission <span class=\"kw-etio\">virale</span> dépend du virus et conditionne la période à risque + la stratégie préventive.</p>\n      <table >\n        <thead><tr><th>Virus</th><th>Voie principale</th><th>Période à risque</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">CMV</span></td><td>Hématogène transplacentaire</td><td><span class=\"kw-chiffre\">≤ 12</span> SA (séquelles neuro)</td></tr>\n          <tr><td>Rubéole</td><td>Hématogène transplacentaire</td><td>&lt; 18-20 SA (<span class=\"kw-ci\">tératogène</span>)</td></tr>\n          <tr><td>Parvovirus B19</td><td>Hématogène transplacentaire</td><td>T1-T2 (anémie fœtale, anasarque)</td></tr>\n          <tr><td><span class=\"kw-etio\">VZV</span></td><td>Hématogène + per-partum</td><td>&lt; 20 SA (embryofœtopathie) ; 5 j avant à 2 j après accouchement (<span class=\"kw-alerte\">varicelle néonatale grave</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\">HSV</span></td><td>Per-partum +++</td><td>Primo-infection T3 (transmission <span class=\"kw-chiffre\">50 %</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\">VHB</span></td><td>Per-partum (<span class=\"kw-chiffre\">90 %</span>) > transplacentaire</td><td>Accouchement</td></tr>\n          <tr><td><span class=\"kw-etio\">VIH</span></td><td>Per-partum (<span class=\"kw-chiffre\">20 %</span>), transplacentaire (<span class=\"kw-chiffre\">6 %</span>), <span class=\"kw-ci\">allaitement</span> (<span class=\"kw-chiffre\">15 %</span>)</td><td>Accouchement et <span class=\"kw-ci\">allaitement</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Grippe</span></td><td>Pas de transmission fœtale directe (pas <span class=\"kw-ci\">tératogène</span>)</td><td>Tous trimestres (risque maternel + FCS, prématurité)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales · 168 — Herpesvirus · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":1},{"id":"27-14","rang":"B","rubrique":"Prise en charge","titre":"Herpes simplex virus (HSV) : connaître les éléments de prévention fœtale","contenu":"<p>L'<span class=\"kw-def\">herpès néonatal</span> est <strong>exceptionnel mais grave</strong> (<span class=\"kw-def\">encéphalite</span>, <span class=\"kw-def\">sepsis</span>, <span class=\"kw-def\">mortalité</span> élevée). La voie de contamination dominante est <strong>per-partum</strong>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Risque de transmission</th><th>CAT</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Primo-infection T3</span> (&lt; 6 sem avant terme)</td><td>Transmission ~<span class=\"kw-chiffre\">50 %</span> — risque maximal</td><td><span class=\"kw-ttt\">Aciclovir</span> suspensif &gt; 36 SA + <strong>césarienne programmée</strong></td></tr>\n          <tr><td>Lésions herpétiques actives au moment du travail</td><td>Risque élevé</td><td><strong>Césarienne</strong> en <span class=\"kw-alerte\">urgence</span></td></tr>\n          <tr><td>Récurrence sans <span class=\"kw-clinique\">lésion</span> en travail</td><td>Faible</td><td>Voie basse possible · <span class=\"kw-ttt\">aciclovir</span> suspensif &gt; 36 SA discutable</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Éviter les manœuvres invasives</strong> : pas d'<span class=\"kw-ci\">électrode de scalp</span>, pas de microprélèvement (<span class=\"kw-bio\">pH</span>/<span class=\"kw-bio\">lactates</span>), pas d'électrode d'<span class=\"kw-bio\">ECG</span> fœtal</li>\n        <li><strong>Pas de <span class=\"kw-def\">dépistage</span> sérologique systématique <span class=\"kw-etio\">HSV</span></strong> chez la femme enceinte</li>\n        <li>Interrogatoire à la recherche d'antécédents personnels ou chez le partenaire</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 168 — Herpesvirus</em></p>","frequence":2},{"id":"27-15","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l'infection à VHB materno-fœtale","contenu":"<p>L'<span class=\"kw-def\">infection à VHB materno-fœtale</span> est l'infection par le virus de l'<span class=\"kw-def\">hépatite</span> B contractée par le fœtus ou le nouveau-né à partir d'une mère porteuse (~ <span class=\"kw-chiffre\">1 %</span> des femmes enceintes en France).</p>\n      <table >\n        <thead><tr><th>Mode</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Per-partum (<span class=\"kw-chiffre\">90 %</span>)</td><td>Contact avec le sang maternel — indépendant de la voie d'accouchement (basse ou césarienne)</td></tr>\n          <tr><td>Transplacentaire</td><td>Possible chez les femmes à <strong>haut taux de réplication <span class=\"kw-etio\">virale</span></strong> (AgHBe+ avec ADN <span class=\"kw-etio\">VHB</span> détectable)</td></tr>\n          <tr><td>Post-natale</td><td><span class=\"kw-ci\">Allaitement</span> (faible, autorisé après sérovaccination)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-etio\">VHB</span> n'est pas <span class=\"kw-ci\">tératogène</span></strong> : pas d'embryofœtopathie, pas d'<span class=\"kw-clinique\">ictère</span> néonatal (délai d'incubation). Mais en cas de transmission, <span class=\"kw-alerte\">80 à 90 % des nouveau-nés développent une hépatite B chronique</span> (<span class=\"kw-bio\">vs</span><span class=\"kw-chiffre\"> 5-10 %</span> chez l'adulte) → <span class=\"kw-def\">cirrhose</span>, CHC.</div>\n      <p>Risque de transmission élevé en l'absence de mesures préventives, majoré par AgHBe+ avec ADN <span class=\"kw-etio\">VHB</span> détectable (<span class=\"kw-chiffre\">90 %</span>) ; AC anti-HBe+ → quasi nul.</p>","frequence":0},{"id":"27-16","rang":"A","rubrique":"Prise en charge","titre":"**Virus de l'hépatite B (VHB) : connaître les éléments de prévention fœtale par la vaccination**","contenu":"<p>La prévention de l'IMF à <span class=\"kw-etio\">VHB</span> repose sur le <strong><span class=\"kw-def\">dépistage</span> obligatoire</strong> + la <strong>sérovaccination du nouveau-né</strong>.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Dépistage</span></td><td><span class=\"kw-bio\">Recherche AgHBs</span> obligatoire dès la déclaration de <span class=\"kw-ci\">grossesse</span> (au 1ᵉʳ trimestre)</td></tr>\n          <tr><td>Mère AgHBs+</td><td>Traitement <span class=\"kw-ttt\">antiviral</span> envisagé pour réduire la charge <span class=\"kw-etio\">virale</span> (<span class=\"kw-ttt\">lamivudine</span> ou <span class=\"kw-ttt\">ténofovir</span>) ; pas de césarienne prophylactique ❌</td></tr>\n          <tr><td>Nouveau-né</td><td><strong>Sérovaccination dès la naissance, avant <span class=\"kw-chiffre\">H12</span></strong> : Ig anti-HBs IM + 1ʳᵉ dose du vaccin <span class=\"kw-etio\">VHB</span> ; schéma complet M0-<span class=\"kw-chiffre\">M1</span>-M6</td></tr>\n          <tr><td><span class=\"kw-def\">Surveillance</span></td><td>À partir de <span class=\"kw-chiffre\">9 mois</span> (et <span class=\"kw-chiffre\">≥ 1 mois</span> après dernière dose) : AgHBs + titrage AC anti-HBs pour vérifier efficacité</td></tr>\n          <tr><td><span class=\"kw-ci\">Allaitement</span></td><td><strong>Autorisé</strong> après sérovaccination (enfant protégé)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Vaccination universelle :</strong> tous les nouveau-nés sont vaccinés contre le <span class=\"kw-etio\">VHB</span> selon le calendrier vaccinal — la sérovaccination s'ajoute aux mères AgHBs+ pour court-circuiter la fenêtre per-partum.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales</em></p>","frequence":1},{"id":"27-17","rang":"A","rubrique":"Prise en charge","titre":"**Virus de l'immunodéficience humaine (VIH) : connaître les éléments de prévention par le dépistage**","contenu":"<p>La transmission materno-fœtale (TMF) du <span class=\"kw-etio\">VIH</span>-1 passe de <span class=\"kw-chiffre\">20-25 %</span> sans traitement à <span class=\"kw-chiffre\">0,3-0,6 %</span> si charge <span class=\"kw-etio\">virale</span> &lt; 50 copies/mL à l'accouchement. <strong>Objectif :</strong> charge virale <span class=\"kw-bio\">indétectable</span> à l'accouchement.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Dépistage</span></td><td><strong>Non obligatoire mais systématiquement proposé</strong> à la déclaration de <span class=\"kw-ci\">grossesse</span> (1ᵉʳ trimestre) ; proposé à nouveau au 3ᵉ trimestre / accouchement dans les milieux à risque ; <span class=\"kw-def\">dépistage</span> du futur père et partenaire</td></tr>\n          <tr><td>Pendant la <span class=\"kw-ci\">grossesse</span></td><td>Toutes les mères traitées (même non éligibles pour elles-mêmes) ; <span class=\"kw-ttt\">trithérapie ARV</span> (2 INTI + 1 IP) ; <span class=\"kw-ci\">éfavirenz CI</span> ⚠️ ; instauration <strong>avant 26 SA</strong> si <span class=\"kw-bio\">CV</span> positive en début</td></tr>\n          <tr><td>Accouchement (<span class=\"kw-bio\">CV</span> indétectable)</td><td>Voie basse possible · <strong>pas de perfusion AZT</strong> · pas de prélèvements au scalp · pas d'électrode d'<span class=\"kw-bio\">ECG</span> fœtal</td></tr>\n          <tr><td>Accouchement (<span class=\"kw-bio\">CV</span> <span class=\"kw-chiffre\">≥ 400</span> copies/mL)</td><td><strong>Césarienne programmée</strong> + perfusion prophylactique <span class=\"kw-ttt\">zidovudine</span> (AZT)</td></tr>\n          <tr><td>Nouveau-né</td><td>Si bilan satisfaisant : <span class=\"kw-ttt\">AZT PO</span> 4 sem ou <span class=\"kw-ttt\">névirapine</span> 15 j ; prophylaxie renforcée (bi/trithérapie) si prématurité, <span class=\"kw-bio\">CV</span> élevée, accouchement compliqué</td></tr>\n          <tr><td><span class=\"kw-ci\">Allaitement</span></td><td><span class=\"kw-ci\">Contre-indication absolue</span> ⚠️ dans les pays économiquement favorisés</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-def\">Dépistage</span> T21 si <span class=\"kw-etio\">VIH</span>+ :</strong> proposer un DPNI (ADN fœtal sur sang maternel) <strong>plutôt qu'un geste invasif</strong> (<span class=\"kw-imagerie\">amniocentèse</span>). <strong>BCG du nouveau-né</strong> : reporté jusqu'à confirmation de l'absence d'infection.</div>\n      <p><span class=\"kw-def\">Suivi</span> nouveau-né : <span class=\"kw-bio\">PCR virale</span> à naissance, <span class=\"kw-chiffre\">M1</span>, M3, M6 (tests sérologiques inutilisables — AC maternels transmis) ; transmission confirmée si 2 <span class=\"kw-bio\">PCR</span> successives positives.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 162 — IST</em></p>","frequence":1},{"id":"27-18","rang":"A","rubrique":"Prise en charge","titre":"Virus varicelle zona (VZV) : connaître les éléments de prévention par la vaccination","contenu":"<p>La varicelle pendant la <span class=\"kw-ci\">grossesse</span> comporte un <strong>risque maternel</strong> (<span class=\"kw-def\">pneumonie</span> varicelleuse — surmortalité), un <strong>risque embryofœtal</strong> et un <strong>risque néonatal grave</strong>.</p>\n      <table >\n        <thead><tr><th>Période</th><th>Risque</th></tr></thead>\n        <tbody>\n          <tr><td>&lt; 20 SA</td><td><span class=\"kw-alerte\">Embryofœtopathie varicelleuse</span> (<span class=\"kw-chiffre\">1-2 %</span>) : hypoplasie membres, atteinte cutanée zostérienne, microphtalmie, microcéphalie</td></tr>\n          <tr><td><span class=\"kw-clinique\">Éruption</span> maternelle 5 j avant à 2 j après accouchement</td><td><span class=\"kw-alerte\">Varicelle néonatale grave</span> — <span class=\"kw-def\">mortalité</span> ~<span class=\"kw-chiffre\">30 %</span> sans traitement</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong><span class=\"kw-def\">Prévention primaire</span></strong> : <span class=\"kw-ttt\">vaccin VZV vivant atténué</span> <strong>avant <span class=\"kw-ci\">grossesse</span></strong> chez femmes non immunes ; <span class=\"kw-ci\">CI pendant la grossesse</span> ⚠️</li>\n        <li><strong>Contage chez femme enceinte non immune</strong> : <span class=\"kw-ttt\">Ig anti-VZV IV</span> dans les <strong><span class=\"kw-chiffre\">96 h</span></strong></li>\n        <li><strong>Varicelle confirmée chez la mère</strong> : <span class=\"kw-ttt\">aciclovir IV</span></li>\n      </ul>\n      <p>Contraception <span class=\"kw-chiffre\">≥ 1 mois</span> après vaccin <span class=\"kw-etio\">VZV</span> (vaccin vivant).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 168 — Herpesvirus</em></p>","frequence":0},{"id":"27-19","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes de transmission materno-fœtale de la listériose","contenu":"<p><span class=\"kw-etio\">Listeria monocytogenes</span> — bactérie Gram+ saprophyte, <span class=\"kw-clinique\">résiste au froid</span> mais <span class=\"kw-clinique\">sensible à la chaleur</span>. Rare (~ 1/<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1000</span> g</span>rossesses) mais sévère.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Contamination maternelle</td><td>Alimentation (fromages au lait cru, charcuterie, produits réfrigérés contaminés)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Diffusion</span></td><td><strong>Bactériémie maternelle</strong> → <strong>transmission transplacentaire hématogène</strong></td></tr>\n          <tr><td>Atteinte placentaire</td><td>Colonisation placentaire → <strong>chorioamniotite</strong> → bactériémie fœtale</td></tr>\n          <tr><td>Manifestation maternelle</td><td>2 phases : <span class=\"kw-clinique\">syndrome pseudo-grippal</span> (assez banal) puis <span class=\"kw-clinique\">chorioamniotite</span> (<strong>travail prématuré fébrile + perte liquidienne vaginale épaisse/teintée</strong>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Conséquences néonatales :</strong> accouchement prématuré, infection néonatale (<span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">50-75 %</span>) — <span class=\"kw-clinique\">cyanose</span>, apnée, <span class=\"kw-alerte\">détresse</span> respiratoire, troubles de la conscience, <span class=\"kw-alerte\">méningite purulente (95 %)</span>.</div>","frequence":0},{"id":"27-20","rang":"A","rubrique":"Prise en charge","titre":"Listériose materno-fœtale (MF) : connaître les éléments de prévention","contenu":"<p>La prévention de la listériose chez la femme enceinte repose sur des <strong>règles d'hygiène alimentaire strictes</strong> (<span class=\"kw-etio\">Listeria</span> résiste au froid mais est tuée par la chaleur <span class=\"kw-chiffre\">≥ 72 °C</span>).</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr><td>Aliments <span class=\"kw-ci\">à éviter</span></td><td><strong>Fromages au lait cru</strong> à pâte molle (camembert, brie, roquefort), fromages vendus râpés, croûtes ; charcuterie cuite consommée en l'état (pâté, rillettes, jambon cuit, produits en gelée) ; poissons fumés, coquillages crus, surimi, tarama ; graines germées crues (soja, luzerne)</td></tr>\n          <tr><td>Précautions cuisson</td><td>Viande consommée <span class=\"kw-clinique\">bien cuite (≥ 72 °C)</span> ou congelée (-<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>18</span> °C</span>) ; réchauffer soigneusement les restes alimentaires</td></tr>\n          <tr><td>Hygiène générale</td><td>Lavage des mains avant/après manipulation d'aliments à risque et jardinage ; nettoyage régulier du réfrigérateur ; séparation aliments crus/cuits</td></tr>\n          <tr><td>Légumes/fruits</td><td>Crudités, fruits, légumes et herbes aromatiques soigneusement lavés</td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-ttt\">Activité physique adaptée</span> :<span class=\"kw-chiffre\"> 30 min</span>, 3 à 5 ×/sem.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span> · 173 — Zoonose</em></p>","frequence":0},{"id":"27-21","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à prescrire en cas de sus-picion de listériose MF","contenu":"<p>Devant tout <strong>syndrome fébrile sans foyer évident</strong> chez la femme enceinte, suspecter une listériose et prescrire :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">Hémocultures</span></strong> (aéro/anaérobies)</td><td>En précisant explicitement <strong>la recherche de <span class=\"kw-etio\">Listeria</span> monocytogenes</strong> au laboratoire</td></tr>\n          <tr><td><span class=\"kw-bio\">ECBU</span> + bilan <span class=\"kw-etio\">inflammatoire</span></td><td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span> — recherche d'autres foyers (<span class=\"kw-def\">pyélonéphrite</span>, chorioamniotite)</td></tr>\n          <tr><td>À l'accouchement</td><td><span class=\"kw-bio\">Hémocultures</span> en cas de reprise fébrile ; examen bactériologique <strong>du placenta + lochies</strong> (presque toujours positif si recueil correct) ; <span class=\"kw-bio\">anatomopathologie</span> placentaire (<strong>granulomes <span class=\"kw-etio\">infectieux</span></strong>)</td></tr>\n          <tr><td>Nouveau-né</td><td><strong><span class=\"kw-bio\">Hémocultures</span>, <span class=\"kw-bio\">LCS</span></strong> (germe facilement isolé en culture), prélèvement de liquide gastrique, méconium, peau</td></tr>\n          <tr><td>Enquête environnementale</td><td>À partir des aliments suspects si suspicion d'épidémie</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste dès la suspicion</strong> (avant résultat des <span class=\"kw-bio\">hémocultures</span>) chez la femme enceinte fébrile avec <span class=\"kw-alerte\">signes de gravité</span> : <span class=\"kw-ttt\">amoxicilline IV</span> (ou <span class=\"kw-ttt\">érythromycine</span> si <span class=\"kw-ci\">allergie</span>). Si confirmation : <strong><span class=\"kw-ttt\">amoxicilline</span> + aminoside 5 j</strong> puis <span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">≥ 4</span> sem ou jusqu'à l'accouchement.</div>","frequence":0},{"id":"27-22","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes de transmission materno-fœtale du streptocoque B","contenu":"<p><span class=\"kw-etio\">Streptococcus agalactiae</span> (SGB) — <strong>bactérie la plus fréquemment en cause dans les infections graves du nouveau-né</strong>.</p>\n      <table >\n        <thead><tr><th>Indicateur</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Prévalence</span> portage en France</td><td><span class=\"kw-chiffre\">10-15 %</span> (<span class=\"kw-chiffre\">10-35 %</span> digestif/vaginal selon Pilly)</td></tr>\n          <tr><td>Colonisation néonatale</td><td><span class=\"kw-chiffre\">50-70 %</span> (Pilly)</td></tr>\n          <tr><td>Risque de transmission néonatale (gynéco)</td><td><span class=\"kw-chiffre\">40-50 %</span></td></tr>\n          <tr><td>Risque d'infection néonatale (Pilly)</td><td><span class=\"kw-chiffre\">1 %</span> des nouveau-nés colonisés</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Colonisation cervico-vaginale maternelle</strong> asymptomatique</li>\n        <li><strong>Transmission per-partum ascendante</strong> lors de l'accouchement ou de la <span class=\"kw-alerte\">rupture</span> prolongée des membranes (RPM)</li>\n        <li>Conséquences néonatales : <span class=\"kw-alerte\">sepsis néonatal précoce</span> (pneumopathie, <span class=\"kw-def\">méningite</span>), <span class=\"kw-alerte\">chorioamniotites</span>, IMF, endométrites du post-partum</li>\n      </ul>","frequence":0},{"id":"27-23","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge médicamenteuse de la vaginose bactérienne","contenu":"<p>La <span class=\"kw-def\">vaginose bactérienne</span> est un déséquilibre de la flore vaginale (lactobacilles → anaérobies : <em>Gardnerella vaginalis</em>, <em>Mobiluncus</em>, Bacteroides, mycoplasmes). <span class=\"kw-def\">Prévalence</span> : <span class=\"kw-chiffre\">7 %</span> au 1ᵉʳ trimestre en France.</p>\n      <table >\n        <thead><tr><th>Traitement</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Métronidazole</span></td><td><span class=\"kw-chiffre\">7 jours</span>, voie orale ou ovule</td></tr>\n          <tr><td><span class=\"kw-ttt\">Clindamycine</span></td><td><span class=\"kw-chiffre\">7 jours</span></td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Indication du <span class=\"kw-def\">dépistage</span></strong> : pas de bénéfice systématique en population générale ; utile si <strong>ATCD d'accouchement prématuré</strong> dans un contexte de chorioamniotite <span class=\"kw-etio\">bactérienne</span> (dépistage par prélèvement vaginal au 1ᵉʳ trimestre)</li>\n        <li><strong>Diagnostic</strong> : <span class=\"kw-def\">critères cliniques</span> d'<span class=\"kw-bio\">Amsel</span> (<span class=\"kw-chiffre\">≥ 3</span>/4 : <span class=\"kw-bio\">pH</span> &gt; 4,5, leucorrhées grisâtres homogènes, clue cells &gt;<span class=\"kw-chiffre\"> 20 %</span>, sniff test positif) et/ou <span class=\"kw-bio\">score de Nugent</span> <span class=\"kw-chiffre\">≥ 7</span> (coloration de Gram)</li>\n        <li><strong><span class=\"kw-def\">Surveillance</span></strong> : contrôle trimestriel (récidive fréquente) ; renouveler le traitement si nécessaire</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — IST</em></p>","frequence":0},{"id":"27-24","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le risque de la vaginose bactérienne au cours de la grossesse","contenu":"<p>La <span class=\"kw-etio\">vaginose</span> <span class=\"kw-etio\">bactérienne</span> expose à des risques infectieux et obstétricaux. Le lien avec l'accouchement prématuré reste modeste mais réel.</p>\n      <ul>\n        <li><strong>Complications obstétricales</strong> : <span class=\"kw-alerte\">menace d'accouchement prématuré (MAP)</span> (odds ratio 1,5 à 2)</li>\n        <li><strong>Infections génitales hautes (IGH)</strong></li>\n        <li><strong>Infections postopératoires</strong> en cas de geste chirurgical par voie vaginale</li>\n        <li><strong>Chorioamniotite</strong> <span class=\"kw-etio\">bactérienne</span></li>\n        <li><strong><span class=\"kw-alerte\">Rupture</span> prématurée des membranes (RPM)</strong></li>\n        <li><strong>Endométrite</strong> du post-partum</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Lien faible mais significatif</strong> avec la prématurité — d'où l'indication de <span class=\"kw-def\">dépistage</span> ciblé en cas d'ATCD d'accouchement prématuré sur chorioamniotite (et non systématique).</div>","frequence":0},{"id":"27-25","rang":"A","rubrique":"Prise en charge","titre":"Grippe et grossesse","contenu":"<p>La femme enceinte est une <strong>population à risque de <span class=\"kw-etio\">grippe</span> sévère</strong> (surtout T2 et T3) — la grippe entraîne plus d'hospitalisations graves chez la femme enceinte que la listériose ou la toxoplasmose.</p>\n      <table >\n        <thead><tr><th>Versant</th><th>Risques</th></tr></thead>\n        <tbody>\n          <tr><td>Maternel</td><td><span class=\"kw-alerte\">Hospitalisation</span> accrue (T2-T3), <span class=\"kw-alerte\">complications pulmonaires</span> (surinfection, <span class=\"kw-def\">OAP</span>), <span class=\"kw-alerte\">complications cardiovasculaires</span>, hospitalisation en réanimation</td></tr>\n          <tr><td>Fœtal</td><td><strong>Pas <span class=\"kw-ci\">tératogène</span> ❌</strong> · avortement, prématurité (lié à la <span class=\"kw-clinique\">fièvre</span> et aux complications maternelles)</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Prévention primaire</span> :</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Vaccination antigrippale</span> = <strong>meilleur moyen de protection</strong>, possible à tous les stades de la <span class=\"kw-ci\">grossesse</span> (<strong>vaccin inactivé</strong>)</li>\n        <li>Passage des AC maternels protège le nouveau-né et le nourrisson de moins de <span class=\"kw-chiffre\">6 mois</span> (non vaccinables)</li>\n        <li>Mesures d'hygiène, limitation des contacts</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Prévention secondaire</span> / traitement post-exposition :</strong></p>\n      <ul>\n        <li>Contage &lt;<span class=\"kw-chiffre\"> 48h</span> : <span class=\"kw-ttt\">oseltamivir prophylactique</span> 1×/j pendant 10 j (sauf si vaccinée)</li>\n        <li>Suspicion <span class=\"kw-etio\">grippe</span> : <span class=\"kw-ttt\">oseltamivir curatif</span> 2×/j pendant 5 j, débuté &lt;<span class=\"kw-chiffre\"> 48 h</span> après les 1ᵉʳˢ signes</li>\n        <li><span class=\"kw-alerte\">Hospitalisation</span> si <span class=\"kw-alerte\">signes de gravité</span> (atteinte fonctions supérieures, FR &gt; 30, PAS &lt; 90, FC &gt; 120)</li>\n        <li><span class=\"kw-ci\">Allaitement</span> maternel possible ✅</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 154 — Infection bronchopulmonaire communautaire</em></p>","frequence":0},{"id":"27-26","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de l'allo-immunisation antiérythrocytaire","contenu":"<p>L'allo-immunisation antiérythrocytaire correspond à la présence chez une femme enceinte d'un <span class=\"kw-def\">AC irrégulier</span> (non-A ou non-B) dirigé contre un <span class=\"kw-bio\">antigène</span> de groupe sanguin érythrocytaire fœtal.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Sensibilisation maternelle</td><td>Passage de GR fœtales incompatibles dans la circulation maternelle (mère <span class=\"kw-ttt\">RhD</span>-, fœtus RhD+) lors d'événements à risque (accouchement, FCS, IVG, GEU, traumatisme abdo, <span class=\"kw-imagerie\">amniocentèse</span>, version par manœuvre externe, <span class=\"kw-ttt\">chirurgie</span> utérine, métrorragies, ou de façon spontanée silencieuse ⚠️) ; ou transfusion non isogroupe (rare)</td></tr>\n          <tr><td>Production d'IgG anti-D</td><td>AC <strong>réguliers IgM</strong> ne passent pas la barrière placentaire ❌ ; AC <strong>irréguliers IgG</strong> passent ✅</td></tr>\n          <tr><td>Passage transplacentaire</td><td>IgG anti-D maternelles traversent le placenta vers la circulation fœtale</td></tr>\n          <tr><td>Hémolyse fœtale</td><td><strong>Anémie hémolytique fœtale</strong> (1ʳᵉ cause d'anémie fœtale) → <span class=\"kw-alerte\">anasarque</span> (épanchements séreux) → <span class=\"kw-alerte\">MFIU</span></td></tr>\n          <tr><td>Atteinte néonatale</td><td>AC maternels persistent plusieurs semaines : <span class=\"kw-alerte\">anémie hémolytique néonatale</span> + <span class=\"kw-alerte\">ictère à bilirubine libre</span> (risque <strong><span class=\"kw-clinique\">ictère</span> nucléaire</strong> = séquelles neuro)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>AC les + fréquents et + graves :</strong> anti-D (Rh1), anti-c (Rh4), anti-Kell. Mère non concernée (ses propres GR n'expriment pas l'Ag).</div>","frequence":1},{"id":"27-27","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le diagnostic de l'allo-immunisation antiérythrocytaire","contenu":"<p>Le diagnostic combine un <strong>versant maternel</strong> (<span class=\"kw-def\">dépistage</span> sérologique de l'allo-immunisation) et un <strong>versant fœtal</strong> (évaluation du risque d'anémie).</p>\n      <table >\n        <thead><tr><th>Versant</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td>Maternel — systématique au 1ᵉʳ trimestre</td><td><strong><span class=\"kw-bio\">Groupe rhésus phénotype</span></strong> (2 déterminations) + <strong><span class=\"kw-bio\">RAI</span></strong> (Recherche d'Agglutinines Irrégulières)</td></tr>\n          <tr><td>Recontrôle RAI</td><td>Indications : femmes <span class=\"kw-ttt\">RhD</span>- ou RhD+ précédemment transfusées · à <strong><span class=\"kw-chiffre\">M6</span>, M8, M9</strong> · inutile si Ig anti-D déjà injectées ou génotypage fœtal RhD-</td></tr>\n          <tr><td>Si RAI positive</td><td>1️⃣ <strong>Identifier l'AC</strong> (anti-D, anti-Kell, anti-c…) · 2️⃣ <strong>Titrage</strong> de l'AC (<span class=\"kw-bio\">Coombs</span> indirect) · 3️⃣ Dosage pondéral des AC anti-Rh (plus précis)</td></tr>\n          <tr><td>Phénotypage père</td><td>Groupe rhésus du conjoint connu chez femmes <span class=\"kw-ttt\">RhD</span>- ; phénotypage père pour autres Ag (Kell…)</td></tr>\n          <tr><td>Fœtal — génotypage <span class=\"kw-ttt\">RhD</span></td><td><span class=\"kw-bio\">PCR sur ADN fœtal circulant</span> dans le sang maternel ; <strong>dès 11 SA</strong> ; uniquement si mère <span class=\"kw-ttt\">RhD</span>-</td></tr>\n          <tr><td>Évaluation anémie fœtale</td><td><span class=\"kw-imagerie\">Doppler artère cérébrale moyenne (PSV-ACM)</span> : <span class=\"kw-radio\">Vmax &gt; 1,5 MoM</span> = anémie significative ; <span class=\"kw-imagerie\">Doppler ombilical</span> ; <span class=\"kw-imagerie\">ECG-tocographie</span> : <span class=\"kw-clinique\">tachycardie</span> ou <span class=\"kw-radio\">rythme sinusoïdal</span> = anémie très sévère</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Seuils à risque fœtal important :</strong> titrage AC ≥ <span class=\"kw-chiffre\">16</span> (1/16) ou dosage pondéral ≥ <span class=\"kw-chiffre\">1 µg/mL</span>. <strong>Anasarque échographique</strong> + tracé sinusoïdal = anémie sévère = <span class=\"kw-alerte\">urgence</span> (Hb &lt;<span class=\"kw-chiffre\"> 5 g/dL</span> le + souvent).</div>","frequence":0},{"id":"27-28","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"**Connaître la prévention de l'allo-immunisation antiérythrocytaire durant la grossesse**","contenu":"<p>La prévention de l'allo-immunisation anti-D chez les femmes <strong><span class=\"kw-ttt\">RhD</span>- non immunisées</strong> repose sur l'injection d'<span class=\"kw-ttt\">immunoglobulines anti-D (Rhophylac®)</span>.</p>\n      <table >\n        <thead><tr><th>Indication</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Prophylaxie systématique à 28 SA / <span class=\"kw-chiffre\">M6</span></strong></td><td><span class=\"kw-ttt\">Ig anti-D <span class=\"kw-chiffre\">300 µg</span> IM</span> (hémorragies fœto-maternelles silencieuses)</td></tr>\n          <tr><td><strong>Prophylaxie ciblée</strong></td><td>Dans les <strong>&lt;<span class=\"kw-chiffre\"> 72 h</span></strong> d'une situation à risque de passage de GR fœtales (FCS, IVG, GEU, <span class=\"kw-imagerie\">amniocentèse</span>, version par manœuvre externe, métrorragies, trauma abdominal, <span class=\"kw-ttt\">chirurgie</span> utérine)</td></tr>\n          <tr><td>Préalable à l'injection</td><td><span class=\"kw-bio\">RAI négative</span> datant de &lt; 1 sem (vérification que la patiente n'est pas déjà immunisée — la RAI se positive transitoirement après l'injection)</td></tr>\n          <tr><td>Doses</td><td><span class=\"kw-chiffre\">200 µg</span> → protection <span class=\"kw-chiffre\">9 sem</span> · <strong><span class=\"kw-chiffre\">300 µg</span> → protection <span class=\"kw-chiffre\">12 sem</span></strong> · <span class=\"kw-chiffre\">≥ 2</span>ᵉ trim : dose calculée selon <span class=\"kw-bio\">test de Kleihauer</span></td></tr>\n          <tr><td>CAT si RAI+ (immunisation déjà constituée)</td><td>Ig anti-D <strong>sans effet</strong> ❌ ; <span class=\"kw-def\">surveillance</span> bimensuelle (titrage, <span class=\"kw-imagerie\">doppler</span> ACM) ; <span class=\"kw-clinique\">transfusion in utero</span> ou <span class=\"kw-clinique\">exsanguinotransfusion in utero</span> si anémie fœtale ; <span class=\"kw-ttt\">corticothérapie</span> + accouchement induit selon terme</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Génotypage <span class=\"kw-ttt\">RhD</span> fœtal</strong> à 11 SA sur ADN fœtal circulant : si fœtus RhD- chez mère RhD- → pas de prophylaxie nécessaire (seul <span class=\"kw-bio\">antigène</span> pris en charge par la sécurité sociale).</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/27/allo-immunisation-schema-resume.png\" alt=\"Schéma résumé d'évaluation et de prévention de l'allo-immunisation maternofœtale Rhésus (versant maternel RAI / versant fœtal génotypage RhD)\" loading=\"lazy\">\n        <figcaption>Schéma résumé d'évaluation et de prévention de l'allo-immunisation maternofœtale Rhésus (rang C). Source : fiche source EDN item 27 — Allo-immunisation maternofoetale Rhésus.</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 24 — Complications de la grossesse · 25 — Grossesse extra-utérine</em></p>","frequence":2},{"id":"27-29","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître la prévention de l'allo-immunisation antiérythrocytaire dans le post-partum","contenu":"<p>La prévention post-partum cible les mères <span class=\"kw-ttt\">RhD</span>- non immunisées dont l'enfant est RhD+.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Groupage du nouveau-né</td><td><span class=\"kw-bio\">Phénotype RhD</span> sur sang du cordon (sauf si génotype fœtal réalisé déjà <span class=\"kw-ttt\">RhD</span>-)</td></tr>\n          <tr><td>Test de <span class=\"kw-bio\">Kleihauer</span></td><td>Sur sang maternel <strong>≥ <span class=\"kw-chiffre\">30 min</span> après la délivrance</strong> — quantifie l'hémorragie fœto-maternelle</td></tr>\n          <tr><td>Injection Ig anti-D</td><td>Si enfant <span class=\"kw-ttt\">RhD</span>+ : <span class=\"kw-ttt\">Ig anti-D dans les 72 h post-accouchement</span>, dose adaptée au <span class=\"kw-bio\">Kleihauer</span> (<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>300</span> µg</span> de base, jusqu'à plusieurs doses si <span class=\"kw-bio\">Kleihauer</span> élevé)</td></tr>\n          <tr><td>Oubli</td><td>Injection encore possible jusqu'à <strong><span class=\"kw-chiffre\">30 jours</span> après l'accouchement</strong></td></tr>\n          <tr><td>Autres événements</td><td>Idem après FCS T2-T3, IVG, GEU</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-bio\">Coombs</span> néonatal positif :</strong> ~<span class=\"kw-chiffre\">10 %</span> des nouveau-nés <span class=\"kw-ttt\">RhD</span>+ de mère ayant reçu Ig anti-D à 28 SA — pas d'exploration complémentaire en l'absence de signes cliniques (<span class=\"kw-clinique\">ictère</span>, anémie).</div>","frequence":0},{"id":"27-30","rang":"A","rubrique":"Prise en charge","titre":"Médicaments et grossesse : connaître la conduite à tenir en cas d'exposition","contenu":"<p>L'évaluation d'une exposition médicamenteuse repose sur la <strong>chronologie</strong>, le <strong>terme d'exposition</strong> et le <strong>profil <span class=\"kw-ci\">tératogène</span></strong> du médicament. Ressource clé : <span class=\"kw-clinique\">CRAT</span> (Centre de Référence sur les Agents Tératogènes — lecrat.fr) et centres régionaux de pharmacovigilance.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td>Patiente prenant un traitement, ne se sachant pas enceinte</td><td>Consigner durée, quantité, indication. Évaluer le risque selon le terme (organogenèse T1) + bénéfice maternel à l'arrêt. Discussion en <strong>comité de diagnostic prénatal (CPDPN)</strong> après information du couple</td></tr>\n          <tr><td>Patiente sous traitement désirant une <span class=\"kw-ci\">grossesse</span></td><td>Consultation préconceptionnelle pour adapter au traitement le mieux connu pour une <span class=\"kw-ci\">grossesse</span> — assistance des CRPV</td></tr>\n          <tr><td>Malformation découverte à la naissance</td><td><span class=\"kw-def\">Prévalence</span> des malformations en population générale ~ <span class=\"kw-chiffre\">2-3 %</span>, dont &lt;<span class=\"kw-chiffre\"> 5 %</span> d'origine médicamenteuse. Reprendre rétrospectivement la chronologie, déclarer au CRPV/ANSM</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Principes fondamentaux :</strong> <span class=\"kw-ci\">ne jamais</span> inquiéter inutilement une patiente après découverte d'une prise médicamenteuse en début de <span class=\"kw-ci\">grossesse</span> ; un traitement chronique ne doit pas être interrompu brutalement ; éviter l'automédication ; en cas de doute, diagnostic anténatal possible pour la majorité des médicaments tératogènes.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 326 — Cadre réglementaire de la prescription</em></p>","frequence":0,"liens":[{"href":"https://www.lecrat.fr/","label":"CRAT — Centre de Référence sur les Agents Tératogènes"}]},{"id":"27-31","rang":"A","rubrique":"Diagnostic positif","titre":"**Médicaments et grossesse : connaître les principaux médicaments à risque**","contenu":"<p>Les médicaments à risque sont classés par <strong>profil de risque</strong> (<span class=\"kw-ci\">tératogène</span>, fœtotoxique, néonatal). En population générale, le risque spontané de malformation majeure est de <span class=\"kw-chiffre\">2-3 %</span>.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Molécules</th><th>Risque tératogène (T1)</th></tr></thead>\n        <tbody>\n          <tr><td>Anticancéreux</td><td><span class=\"kw-ttt\">Méthotrexate</span> fortes doses, <span class=\"kw-ttt\">cyclophosphamide</span></td><td><span class=\"kw-ci\">CI absolue</span> — anomalies fermeture tube neural, dysmorphie</td></tr>\n          <tr><td>Antiépileptiques</td><td><span class=\"kw-ttt\">Valproate de sodium</span> (× 4-5), <span class=\"kw-ttt\">carbamazépine</span>, <span class=\"kw-ttt\">phénytoïne</span>, <span class=\"kw-ttt\">phénobarbital</span>, <span class=\"kw-ttt\">topiramate</span></td><td>Spina bifida (AFTN), cardiopathies (CIA, CIV), fentes faciales, hypospadias, retard psychomoteur</td></tr>\n          <tr><td><span class=\"kw-ttt\">Rétinoïdes</span></td><td><span class=\"kw-ttt\">Isotrétinoïne</span> (Roaccutane®), <span class=\"kw-ttt\">acitrétine</span></td><td><span class=\"kw-ci\">CI</span> ·<span class=\"kw-chiffre\"> 25-30 %</span> de malformations (SNC, oreille externe, cœur, squelette) ; contraception <span class=\"kw-chiffre\">2 ans</span> après arrêt acitrétine</td></tr>\n          <tr><td>Thymorégulateur</td><td><span class=\"kw-ttt\">Lithium</span> (Téralithe®)</td><td>Malformations cardiaques (<span class=\"kw-alerte\">Ebstein</span>, CA, CIV)<span class=\"kw-chiffre\"> 4-8 %</span></td></tr>\n          <tr><td>Anti-vit K</td><td><span class=\"kw-ttt\">Warfarine</span></td><td>Warfarin fetal syndrome <span class=\"kw-chiffre\">4-6 %</span> (dysmorphie, hypoplasie phalanges, anomalies cérébrales) ; relais <span class=\"kw-ttt\">HBPM</span> en vue <span class=\"kw-ci\">grossesse</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Immunosuppresseurs</span></td><td><span class=\"kw-ttt\">Mycophénolate</span> (CellCept®)</td><td>FCS <span class=\"kw-chiffre\">50 %</span> ; anomalies oreille externe, fente labio-palatine, micrognathie</td></tr>\n          <tr><td>Prostaglandines</td><td><span class=\"kw-ttt\">Misoprostol</span></td><td><span class=\"kw-alerte\">Syndrome de Moebius</span>, rétrognathie, anomalies membres</td></tr>\n          <tr><td>Antithyroïdiens</td><td><span class=\"kw-ttt\">Carbimazole</span></td><td>Aplasie cuir chevelu, atrésie choanes/œsophage, omphalocèle (remplacer par PTU au T1)</td></tr>\n          <tr><td>Virostatiques</td><td><span class=\"kw-ttt\">Ribavirine</span>, <span class=\"kw-ttt\">éfavirenz</span></td><td>Malformations faciales, membres, tube neural</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">AINS</span></strong> (T2-T3)</td><td><span class=\"kw-ttt\">Aspirine</span> (sauf faible dose &lt;<span class=\"kw-chiffre\"> 100 mg</span>/j), <span class=\"kw-ttt\">ibuprofène</span>, célécoxib</td><td><span class=\"kw-ci\">CI absolue ≥ 24 SA</span> ⚠️ : fermeture prématurée canal artériel, HTAP fœtale, oligoamnios, IR fœtale</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">IEC</span> / <span class=\"kw-ttt\">ARA2</span></strong> (T2-T3)</td><td>Enalapril, <span class=\"kw-ttt\">losartan</span>…</td><td><span class=\"kw-ci\">CI T2-T3</span> : oligoamnios, IR fœtale et néonatale, anomalies voûte crânienne</td></tr>\n          <tr><td>Thalidomide / lénalidomide</td><td>—</td><td><span class=\"kw-ci\">CI absolue</span> ·<span class=\"kw-chiffre\"> 30-40 %</span> phocomélie</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Antibiotiques <span class=\"kw-ci\">à éviter</span> :</strong> tétracyclines (coloration dentaire), aminosides (atteinte cochléovestibulaire), quinolones (risque ostéoarticulaire). Aucun ATB n'est <em>formellement</em> CI — priorité au bénéfice maternel.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 326 — Cadre réglementaire de la prescription</em></p>","frequence":1},{"id":"27-32","rang":"B","rubrique":"Diagnostic positif","titre":"Médicaments et grossesse : connaître les conséquences des principaux médicaments à risque","contenu":"<p>Les conséquences dépendent de la <strong>fenêtre d'exposition</strong> — c'est le piège QCM central de l'item.</p>\n      <table >\n        <thead><tr><th>Fenêtre</th><th>Terme</th><th>Conséquence type</th></tr></thead>\n        <tbody>\n          <tr><td>Péri-implantatoire</td><td>&lt; J12</td><td><strong>Tout ou rien</strong> : mort embryonnaire <strong>ou</strong> aucun effet (sauf médicaments à demi-vie longue)</td></tr>\n          <tr><td>Embryonnaire (organogenèse)</td><td>J13 – J56 (T1)</td><td><strong>Période de sensibilité maximale aux effets tératogènes</strong> → malformations structurelles</td></tr>\n          <tr><td>Fœtale</td><td>T2 et T3</td><td>Effets fœtotoxiques : <span class=\"kw-alerte\">atteinte de la croissance</span>, <span class=\"kw-alerte\">atteinte de la maturation histologique</span>, <span class=\"kw-alerte\">atteinte fonctionnelle des organes en place</span></td></tr>\n          <tr><td>Fin de <span class=\"kw-ci\">grossesse</span> / accouchement</td><td>T3 / per-partum</td><td>Effets néonataux : <span class=\"kw-ttt\">sevrage</span>, <span class=\"kw-alerte\">détresse</span> respiratoire, hypoglycémie/<span class=\"kw-clinique\">bradycardie</span> (BB-)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Exemples concrets par profil :</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">AINS T2-T3</span> : <span class=\"kw-alerte\">fermeture prématurée canal artériel</span>, HTAP fœtale, IR néonatale, hémorragie néonatale — <span class=\"kw-ci\">CI absolue ≥ 24 SA</span> (exception : <span class=\"kw-ttt\">aspirine</span> faible dose &lt;<span class=\"kw-chiffre\"> 100 mg</span>/j pour prééclampsie/SAPL jusqu'à 36 SA)</li>\n        <li><span class=\"kw-ttt\">IEC / ARA2 T2-T3</span> : oligoamnios, IR fœtale et néonatale, anomalies voûte crânienne</li>\n        <li><span class=\"kw-ttt\">Inducteurs enzymatiques</span> (<span class=\"kw-ttt\">rifampicine</span>, <span class=\"kw-ttt\">phénobarbital</span>, carbamazépine) : déficit en vitamine K néonatale → <span class=\"kw-clinique\">supplémentation vitamine K orale</span> aux 2 derniers trimestres chez la mère + vitamine K1 chez nouveau-né</li>\n        <li><span class=\"kw-ttt\">Psychotropes T3</span> (<span class=\"kw-ttt\">ISRS</span>, BZD, antipsychotiques, imipraminiques) : <span class=\"kw-alerte\">détresse</span> respiratoire, <span class=\"kw-alerte\">syndrome de sevrage néonatal</span> ou sérotoninergique, hypertonie, troubles succion (privilégier demi-vies courtes)</li>\n        <li><span class=\"kw-ttt\">Bêtabloquants</span> (<span class=\"kw-ttt\">propranolol</span>, <span class=\"kw-ttt\">labétalol</span>) : <span class=\"kw-alerte\">hypoglycémie + bradycardie</span> néonatale, RCIU si traitement prolongé — prévenir l'équipe pédiatrique</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/27/sensibilite-foetale-terme.png\" alt=\"Sensibilité fœtale en fonction du terme — schéma chronologique des 4 fenêtres : péri-implantatoire (tout ou rien), embryonnaire (tératogenèse T1), fœtale T2-T3 (fœtotoxicité), accouchement (effets néonataux)\" loading=\"lazy\">\n        <figcaption>Sensibilité fœtale en fonction du terme : 4 fenêtres d'exposition aux médicaments. Source : fiche source EDN item 27 — Médicaments et <span class=\"kw-ci\">grossesse</span>.</figcaption>\n      </figure>","frequence":2},{"id":"27-33","rang":"A","rubrique":"Prise en charge","titre":"**Vaccins et grossesse**","contenu":"<p>La règle générale : <strong>vaccins inactivés autorisés</strong> · <strong>vaccins vivants atténués théoriquement <span class=\"kw-ci\">contre-indiqués</span></strong>. Néanmoins, en cas de vaccination par inadvertance, <strong>pas d'interruption de <span class=\"kw-ci\">grossesse</span></strong> et <strong>pas d'inquiétude à transmettre à la patiente</strong>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Vaccins concernés</th><th>Pendant la grossesse</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Vaccins vivants atténués</strong></td><td><span class=\"kw-ttt\">ROR</span> (rougeole-oreillons-rubéole), <span class=\"kw-ttt\">varicelle</span>, <span class=\"kw-ttt\">BCG</span>, <span class=\"kw-ttt\">poliomyélite</span> (oral), <span class=\"kw-ttt\">rotavirus</span>, <span class=\"kw-ttt\">fièvre jaune</span></td><td><span class=\"kw-ci\">Théoriquement CI</span> · <span class=\"kw-clinique\">fièvre</span> jaune : exception si zone endémique inévitable (bénéfice/risque favorable)</td></tr>\n          <tr><td><strong>Vaccins inactivés autorisés</strong></td><td><span class=\"kw-ttt\">Grippe</span> (recommandé +++), <span class=\"kw-ttt\">dTPa</span> coqueluche (20-36 SA, protection nouveau-né), <span class=\"kw-ttt\">COVID</span>, <span class=\"kw-ttt\">VHA</span>, <span class=\"kw-ttt\">VHB</span>, <span class=\"kw-ttt\">méningo</span>, <span class=\"kw-ttt\">pneumo</span>, <span class=\"kw-ttt\">rage</span>, polio injectable</td><td>Autorisés à tous les trimestres</td></tr>\n          <tr><td>Risque fœtal théorique</td><td>Vaccins responsables d'une <span class=\"kw-alerte\">réaction vaccinale importante avec fièvre</span> : diphtérie, coqueluche, <span class=\"kw-clinique\">fièvre</span> jaune</td><td><span class=\"kw-def\">Surveillance</span> maternelle</td></tr>\n          <tr><td>Innocuité non prouvée</td><td>Choléra, VHA, typhoïde</td><td>À discuter selon séjour en zone à risque</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Vaccin antigrippal recommandé +++</strong> chez la femme enceinte, notamment chez les patientes à risque (<span class=\"kw-def\">diabète</span>, <span class=\"kw-etio\">obésité</span>) — femmes enceintes plus à risque de complications pulmonaires et cardiovasculaires au T2-T3.</div>\n      <p>Délai après vaccin vivant atténué : contraception <span class=\"kw-chiffre\">≥ 1 mois</span> avant <span class=\"kw-ci\">grossesse</span>.</p>","frequence":1},{"id":"27-34","rang":"B","rubrique":"Physiopathologie","titre":"Tabac et grossesse : connaître la physiopathologie","contenu":"<p>La fumée de <span class=\"kw-etio\">tabac</span> contient &gt; <span class=\"kw-chiffre\">4000 produits toxiques</span>. L'atteinte fœtale est <strong>dose-dépendante</strong> et liée à l'interaction de facteurs sociodémographiques, épidémiologiques et génétiques.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-etio\">Toxique</span></th><th>Mécanisme physiopathologique</th></tr></thead>\n        <tbody>\n          <tr><td>Nicotine</td><td>Vasoconstriction utéro-placentaire → <span class=\"kw-alerte\">hypoperfusion placentaire</span> chronique</td></tr>\n          <tr><td>Monoxyde de carbone (CO)</td><td>Liaison à l'Hb (HbCO) → <span class=\"kw-alerte\">diminution du transport d'O₂</span> au fœtus → hypoxie chronique</td></tr>\n          <tr><td>Métabolites cytochrome P450 / glutathione S-transférase</td><td>Polymorphisme <span class=\"kw-etio\">génétique</span> influence la sensibilité — chez les mères de petits poids, davantage de polymorphismes de l'un ou l'autre de ces <span class=\"kw-chiffre\">2 g</span>ènes</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Effet majoré au 3ᵉ trimestre :</strong> les patientes sevrées aux T1-T2 ont des nouveau-nés au poids quasi normal ; l'effet sur la croissance est surtout au T3.</div>","frequence":0},{"id":"27-35","rang":"A","rubrique":"Diagnostic","titre":"Connaître les conséquences d'une intoxication tabagique pendant la grossesse","contenu":"<p>Dans la plupart des pays européens, le <span class=\"kw-etio\">tabagisme</span> en cours de <span class=\"kw-ci\">grossesse</span> est <strong>la principale cause évitable de <span class=\"kw-def\">morbidité</span> périnatale</strong>. <span class=\"kw-chiffre\">~17 %</span> des femmes enceintes continuent à fumer jusqu'à la fin de la grossesse.</p>\n      <table >\n        <thead><tr><th>Période</th><th>Conséquences</th></tr></thead>\n        <tbody>\n          <tr><td>Fertilité</td><td>Stérilité (RR&gt;2 : 2 × plus de cycles nécessaires)</td></tr>\n          <tr><td>T1</td><td><strong>1ʳᵉ cause de <span class=\"kw-alerte\">GEU</span></strong> (RR &gt; 2) · <span class=\"kw-alerte\">FCS</span> dose-dépendantes (RR ≈ 2) · effets tératogènes réels mais faibles</td></tr>\n          <tr><td>T2-T3</td><td><span class=\"kw-alerte\">RCIU</span> dose-dépendant (apparaît préférentiellement 2ᵉ moitié de <span class=\"kw-ci\">grossesse</span>) · <span class=\"kw-alerte\">prématurité</span> (faible mais significatif) · <span class=\"kw-alerte\">placenta praevia</span> (+<span class=\"kw-chiffre\"> 30 %</span>) · <span class=\"kw-alerte\">HRP (× 2)</span> · césarienne ↑ si &gt; <span class=\"kw-chiffre\">20 cig/j</span></td></tr>\n          <tr><td>Néonatal</td><td><strong>Mort inattendue/subite du nourrisson</strong> (× 2 même en environnement non fumeur ⭐) · infections respiratoires basses + otites (+<span class=\"kw-chiffre\"> 50 %</span>) · <span class=\"kw-etio\">obésité</span> de l'adolescent</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Effet-dose démontré</strong> entre <span class=\"kw-etio\">tabagisme</span> maternel et atteinte fœtale. Même le <span class=\"kw-etio\">tabagisme passif</span> a un effet significatif sur le RCIU.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction au <span class=\"kw-etio\">tabac</span></em></p>","frequence":0},{"id":"27-36","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge des femmes enceintes fumeuses","contenu":"<p>Environ <span class=\"kw-chiffre\">50 %</span> des femmes fumeuses arrêtent spontanément sans aide médicamenteuse. Le <span class=\"kw-ttt\">sevrage</span> est bénéfique <strong>à tous les stades de la <span class=\"kw-ci\">grossesse</span></strong>.</p>\n      <table >\n        <thead><tr><th>Type</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Médicamenteuse</td><td><span class=\"kw-ttt\">Substituts nicotiniques</span> autorisés pendant la <span class=\"kw-ci\">grossesse</span> (en cas de dépendance pharmacologique) ; <span class=\"kw-ci\">varénicline et bupropion CI</span></td></tr>\n          <tr><td>Évaluation objective</td><td><span class=\"kw-bio\">Analyseur de CO expiré</span> — mesure objective remise à la patiente</td></tr>\n          <tr><td>Non médicamenteuse</td><td>Conseil minimal de <span class=\"kw-ttt\">sevrage</span> · intervention brève (questions ouvertes) · <strong>entretien motivationnel</strong> · TCC · consultation psychologique · consultation addictologie si polyconsommation</td></tr>\n          <tr><td>Prévention rechutes</td><td>~2/3 des patientes sevrées rechutent à<span class=\"kw-chiffre\"> 6 mois</span> et &gt;3/<span class=\"kw-chiffre\">4 à 1 an</span> · anticipation avec tabacologue en cours de <span class=\"kw-ci\">grossesse</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction au <span class=\"kw-etio\">tabac</span></em></p>","frequence":0},{"id":"27-37","rang":"A","rubrique":"Diagnostic","titre":"Connaître les conséquences d'une alcoolisation pendant la grossesse : syndrome d'alcoolisation fœtale (SAF) et ensemble des troubles causés par l'alcoolisation fœtale (ETCAF)","contenu":"<p>Le <span class=\"kw-def\">SAF</span> est la <strong>principale complication d'une alcoolisation chronique pendant la <span class=\"kw-ci\">grossesse</span></strong>. Fréquence en France : <span class=\"kw-chiffre\">1 à 2/1000</span> sous sa forme complète. <strong>1ʳᵉ cause évitable de retard mental d'origine non <span class=\"kw-etio\">génétique</span>.</strong></p>\n      <p><strong>Le SAF associe 4 éléments à divers degrés :</strong></p>\n      <table >\n        <thead><tr><th>Élément</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td>Retard de croissance</td><td>Modéré dans <span class=\"kw-chiffre\">80 %</span> des cas, <strong>harmonieux</strong> (os longs + périmètre abdo + PC — toxicité directe sur les cellules neurologiques)</td></tr>\n          <tr><td><span class=\"kw-alerte\">Dysmorphie craniofaciale</span></td><td>Hypertrichose + synophris (monosourcil), <span class=\"kw-clinique\">fentes palpébrales étroites</span>, ptosis, épicanthus, hypertélorisme, oreilles basses mal ourlées, ensellure nasale prononcée, nez court, <span class=\"kw-clinique\">allongement et effacement du philtrum</span> (« en verre de montre »), <span class=\"kw-clinique\">lèvre supérieure mince</span>, menton effacé, rétrognathisme</td></tr>\n          <tr><td>Retard des acquisitions</td><td>Troubles cognitifs et comportementaux, retard mental dans formes sévères → handicap</td></tr>\n          <tr><td>Malformations</td><td><span class=\"kw-chiffre\">10-30 %</span> des formes sévères : neurologiques (<span class=\"kw-alerte\">spina bifida</span>, agénésie corps calleux, hydrocéphalie), cardiaques (CIA, CIV), squelettiques (scoliose), fentes labiopalatines</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>ETCAF</strong> (ensemble des troubles causés par l'alcoolisation fœtale) : remplace SAF quand les troubles surviennent <strong>sans retard de croissance ni dysmorphie</strong>, lorsque l'alcoolisation est plus modérée. Fréquence ~ <span class=\"kw-chiffre\">5/1000</span>. Manifestations : baisse du QI, retard langage/écriture, agressivité, hyperactivité, troubles de la motricité fine.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 76 — Addiction à l'<span class=\"kw-etio\">alcool</span></em></p>","frequence":0},{"id":"27-38","rang":"B","rubrique":"Physiopathologie","titre":"Alcool et grossesse : mécanisme – relation dose-effet","contenu":"<p>L'atteinte fœtale est liée au <strong>passage rapide de l'<span class=\"kw-etio\">alcool</span> à travers le placenta</strong>. Le taux d'<span class=\"kw-etio\">alcool</span> fœtal est <strong>quasiment identique</strong> à celui de la mère.</p>\n      <table >\n        <thead><tr><th>Niveau de consommation</th><th>Conséquences fœtales</th></tr></thead>\n        <tbody>\n          <tr><td>Consommation importante (&gt; 2 <span class=\"kw-bio\">VS</span>/j)</td><td>Retentissement fœtal documenté : <span class=\"kw-alerte\">risque de SAF</span></td></tr>\n          <tr><td>Consommation occasionnelle légère/modérée (1-2 <span class=\"kw-bio\">VS</span>/j)</td><td>Pas de syndrome dysmorphique ou malformatif · troubles comportementaux, affectifs et anxieux possibles</td></tr>\n          <tr><td>Binge drinking début de <span class=\"kw-ci\">grossesse</span> (≥ <span class=\"kw-chiffre\">4 verres</span> en 1 fois)</td><td>Pas d'impact démontré si épisode isolé (situation fréquente, <span class=\"kw-ci\">grossesse</span> encore inconnue)</td></tr>\n          <tr><td>Binge drinking T2-T3</td><td>Risques de <span class=\"kw-alerte\">troubles cognitifs</span> par altération de la migration neuronale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Mécanisme central :</strong> atteinte neurologique = arrêts/déviations de la <span class=\"kw-clinique\">migration neuronale</span> (fin T1 → naissance). <strong>Recommandation officielle :</strong> <span class=\"kw-chiffre\">zéro alcool</span> pendant la <span class=\"kw-ci\">grossesse</span> — <strong>absence d'effet seuil démontré</strong>.</div>\n      <p>Rassurer/déculpabiliser une patiente présentant une alcoolisation légère ou un binge drinking isolé en début de <span class=\"kw-ci\">grossesse</span> — l'objectif est de maintenir le lien médecin-patiente, pas d'aggraver la culpabilité.</p>","frequence":1},{"id":"27-39","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Alcool et grossesse : dépistage","contenu":"<p>~ <span class=\"kw-chiffre\">3 %</span> des femmes enceintes consomment de l'<span class=\"kw-etio\">alcool</span> de façon épisodique ou régulière en sachant être enceintes. La <span class=\"kw-ci\">grossesse</span> est une occasion unique de dépister.</p>\n      <table >\n        <thead><tr><th>Outil</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Interrogatoire</strong> (clé du <span class=\"kw-def\">dépistage</span>)</td><td>À chaque consultation prénatale</td></tr>\n          <tr><td>Auto-questionnaire <span class=\"kw-bio\">T-ACE</span></td><td>Meilleure sensibilité que l'interrogatoire seul. <span class=\"kw-def\">Score</span> ≥ <span class=\"kw-chiffre\">2 points</span> = positif. <strong>T</strong>olerance (<span class=\"kw-chiffre\">≥ 3</span> verres = 2 pts), <strong>A</strong>nnoyance, <strong>C</strong>ut-down, <strong>E</strong>ye-opener (1 pt chacun si oui)</td></tr>\n          <tr><td>Dosages biologiques</td><td>Sensibilité ~<span class=\"kw-chiffre\">50 %</span> pour alcoolisation excessive (<span class=\"kw-chiffre\">≥ 2</span> verres/j) — peu performants</td></tr>\n          <tr><td>CAT en cas de consommation</td><td>Cadre exempt de jugement · maintenir le lien · aide au <span class=\"kw-ttt\">sevrage</span> par <span class=\"kw-ttt\">acamprosate (Aotal®)</span> ; cure, foyer thérapeutique, <span class=\"kw-alerte\">hospitalisation</span> ; <span class=\"kw-def\">surveillance</span> échographique ; supplémentation B1-B6 si carence <span class=\"kw-bio\">folates</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Mesures associées :</strong> rechercher autres vulnérabilités (drogues, violence conjugale), PEC sociale, orthophonie/scolarité adaptée pour dépister précocement ETCAF.</p>","frequence":0},{"id":"27-40","rang":"B","rubrique":"Physiopathologie","titre":"Addictologie et grossesse : produits en cause et leurs principaux effets","contenu":"<table >\n        <thead><tr><th>Produit</th><th>Passage</th><th>Effets fœtaux/néonataux</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Cannabis (THC)</span></td><td>Liposoluble → barrière placentaire en quelques min · concentration ↑ × 8 dans le lait maternel</td><td>RCIU par hypoperfusion placentaire ; consommation régulière (<span class=\"kw-chiffre\">≥ 6</span>×/sem) : prématurité, ↓ poids naissance, <span class=\"kw-alerte\">syndrome de sevrage néonatal</span> modéré (trémulations) régressif</td></tr>\n          <tr><td><span class=\"kw-etio\">Cocaïne</span></td><td>Barrière placentaire + lait maternel</td><td><span class=\"kw-def\">HTA</span> + vasoconstriction → <span class=\"kw-alerte\">FCS, prématurité, RCIU, hydramnios, RPM, HRP ⭐ (RR 4-5)</span> · syndrome d'imprégnation néonatal (hypertonie, trémulations, <span class=\"kw-clinique\">convulsions</span>) · entérocolites ulcéronécrosantes, <span class=\"kw-clinique\">infarctus</span> mésentériques</td></tr>\n          <tr><td><span class=\"kw-etio\">Opiacés / héroïne</span></td><td>Barrière placentaire + lait maternel</td><td><span class=\"kw-ci\">Grossesse</span> à haut risque : <strong>manque maternel</strong> → souffrance fœtale, MFIU possible ; FCS, prématurité, RCIU ; <span class=\"kw-alerte\">syndrome de sevrage néonatal</span><span class=\"kw-chiffre\"> 60 %</span> (<span class=\"kw-chiffre\">J0</span> à J10, durée 1-3 sem)</td></tr>\n          <tr><td>Benzodiazépines</td><td>Barrière placentaire</td><td>Syndrome de <span class=\"kw-ttt\">sevrage</span> néonatal plus tardif/long, hypotonie, floppy baby</td></tr>\n          <tr><td>Amphétamines / ecstasy / LSD</td><td>—</td><td>Risques mal connus (usage récréatif souvent interrompu à la découverte de <span class=\"kw-ci\">grossesse</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Héroïne et <span class=\"kw-etio\">opiacés</span> ne sont pas tératogènes</strong> — la gravité vient du manque maternel, des conditions de vie, et du <span class=\"kw-alerte\">syndrome de sevrage néonatal</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 78 — Addiction aux drogues · 79 — Addiction comportementale</em></p>","frequence":0},{"id":"27-41","rang":"A","rubrique":"Diagnostic","titre":"Repérage des conduites addictives et des facteurs de risques associés au cours de la grossesse","contenu":"<p>Le repérage des conduites addictives s'effectue par l'interrogatoire systématique à chaque consultation prénatale, complété par la recherche de <span class=\"kw-def\">facteurs de risque</span> associés.</p>\n      <ul>\n        <li><strong>Interrogatoire</strong> systématique à chaque consultation prénatale : <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">alcool</span>, cannabis, <span class=\"kw-etio\">opiacés</span>, BZD, médicaments détournés</li>\n        <li><strong>Questionnaires validés</strong> : <span class=\"kw-bio\">T-ACE</span> (<span class=\"kw-etio\">alcool</span>), aide au repérage de la dépendance et du mésusage</li>\n        <li><strong>FR associés à rechercher</strong> : précarité, IST, troubles psychiatriques, antécédents traumatiques, polyconsommations, violences conjugales</li>\n        <li><strong>Mesure objective</strong> : analyseur de CO (<span class=\"kw-etio\">tabac</span>), dosages biologiques (<span class=\"kw-etio\">alcool</span>, peu sensibles), <span class=\"kw-def\">dépistage</span> urinaire (cannabis, <span class=\"kw-etio\">opiacés</span>) si pertinent</li>\n        <li><strong>Accompagnement multidisciplinaire</strong> : sage-femme + addictologue + psychiatre + travailleur social + PMI</li>\n      </ul>\n      <p>Ressources : <span class=\"kw-clinique\">CRAT</span> (lecrat.fr) et <span class=\"kw-clinique\">CRPV</span> pour l'évaluation des risques <span class=\"kw-etio\">médicamenteux</span> pendant la <span class=\"kw-ci\">grossesse</span>.</p>","frequence":0},{"id":"27-42","rang":"B","rubrique":"Prise en charge","titre":"Addictologie et grossesse : aspects essentiels de la prise en charge obstétricale et addictologique","contenu":"<p>Le principe central : <strong>préserver le fœtus de la souffrance du manque</strong> sans imposer un <span class=\"kw-ttt\">sevrage</span> brutal qui aggraverait le <span class=\"kw-def\">pronostic</span>.</p>\n      <table >\n        <thead><tr><th>Conduite</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ci\">Sevrage opiacés non recommandé ❌</span></td><td><strong>Déconseillé au T1</strong> (risque FCS) · <strong>déconseillé au T3</strong> (risque accouchement prématuré) · envisageable au T2 si patiente insistante (long, prudent, risque élevé de rechute)</td></tr>\n          <tr><td>Traitement de substitution <span class=\"kw-etio\">opiacés</span> ✅</td><td><span class=\"kw-ttt\">Méthadone</span> (sirop/gélule) <strong>ou</strong> <span class=\"kw-ttt\">buprénorphine</span> (sublingual) — association sans AMM ; doses efficaces pour éviter le manque (souvent augmentées en fin de <span class=\"kw-ci\">grossesse</span>)</td></tr>\n          <tr><td>Pluridisciplinarité</td><td>Sage-femme + obstétricien + addictologue + psychiatre + travailleur social ; <span class=\"kw-def\">surveillance</span> échographique renforcée</td></tr>\n          <tr><td>Planification accouchement</td><td>Maternité de niveau adapté, équipe addicto informée à l'avance</td></tr>\n          <tr><td>Médicaments <span class=\"kw-ci\">à éviter</span> péri-partum</td><td>BZD et <span class=\"kw-etio\">opiacés</span> à courte durée d'action (<span class=\"kw-ttt\">sevrage</span> néonatal)</td></tr>\n          <tr><td><span class=\"kw-ci\">Allaitement</span></td><td>Compatible avec <span class=\"kw-ttt\">méthadone</span>/<span class=\"kw-ttt\">buprénorphine</span> à dose stable (sauf <span class=\"kw-etio\">VIH</span> non contrôlé ou cocaïne)</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"27-43","rang":"B","rubrique":"Prise en charge","titre":"Addictologie et grossesse : accueil de l'enfant","contenu":"<p>L'accueil du nouveau-né de mère addicte impose une <span class=\"kw-def\">surveillance</span> néonatale rigoureuse du <strong>syndrome de <span class=\"kw-ttt\">sevrage</span></strong>.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Évaluation</td><td><span class=\"kw-bio\">Score de Finnegan</span> (ou Lipsitz) toutes les <span class=\"kw-chiffre\">4 h</span> dès la naissance, jusqu'à 3-10 j</td></tr>\n          <tr><td>Survenue</td><td>Délai &lt; 3 j post-naissance (jusqu'à 1-10 j), durée <span class=\"kw-chiffre\">1-3 semaines</span> · fréquence <span class=\"kw-chiffre\">60 %</span> chez nouveau-nés exposés aux <span class=\"kw-etio\">opiacés</span>/TSO</td></tr>\n          <tr><td>Symptômes</td><td>Trémulations, hypertonie, hyperréflexie, troubles du sommeil, pleurs incoercibles, troubles de la succion, <span class=\"kw-clinique\">hyperthermie</span>, mauvaise courbe pondérale, troubles digestifs</td></tr>\n          <tr><td>Traitement</td><td>Si <strong><span class=\"kw-def\">score</span> &gt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>8</span> l</span>ors de 3 évaluations consécutives</strong> : <span class=\"kw-ttt\">chlorhydrate ou sulfate de morphine</span> PO (morphinique de remplacement)</td></tr>\n          <tr><td><span class=\"kw-ci\">Allaitement</span></td><td>Encouragé si TSO stable (<span class=\"kw-ttt\">méthadone</span>, <span class=\"kw-ttt\">buprénorphine</span>) · CI <span class=\"kw-etio\">VIH</span>, cocaïne active</td></tr>\n          <tr><td><span class=\"kw-def\">Suivi</span></td><td>Pédiatrique au long cours · signalement PMI/ASE selon contexte social</td></tr>\n        </tbody>\n      </table>\n      <p>Sévérité du <span class=\"kw-ttt\">sevrage</span> non corrélée à la posologie du TSO, mais majorée par les co-prises (BZD → sevrage plus tardif et plus long).</p>","frequence":0},{"id":"27-44","rang":"B","rubrique":"Diagnostic","titre":"Addictologie et grossesse : conséquences à long terme","contenu":"<ul>\n        <li><span class=\"kw-alerte\">Troubles neurodéveloppementaux</span> : cognition, attention, comportement</li>\n        <li><span class=\"kw-alerte\">Troubles psychiatriques</span> à l'adolescence et à l'âge adulte</li>\n        <li><span class=\"kw-alerte\">Vulnérabilité aux addictions</span> chez l'enfant et l'adolescent (transmission psycho-socio-environnementale)</li>\n        <li><span class=\"kw-alerte\">Troubles de l'attachement</span> et parentalité fragile</li>\n        <li>Mort inattendue/subite du nourrisson (<span class=\"kw-etio\">tabagisme</span>, polyconsommations)</li>\n        <li>Difficultés scolaires, troubles d'apprentissage (cannabis), hyperactivité, troubles du sommeil</li>\n      </ul>\n      <p>Le repérage précoce et la mise en place d'un <span class=\"kw-def\">suivi</span> pédiatrique et orthophonique adapté limite le handicap social et fonctionnel à long terme.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction au <span class=\"kw-etio\">tabac</span> · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 78 — Addiction aux drogues</em></p>","frequence":0},{"id":"27-45","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes d'action de l'irradiation sur le fœtus","contenu":"<p>L'<span class=\"kw-clinique\">irradiation</span> fœtale se mesure en <strong>milligrays (mGy)</strong>. Deux mécanismes d'action s'opposent : <strong>effets déterministes</strong> (à seuil, mort cellulaire) et <strong>effets stochastiques</strong> (sans seuil, lésions ADN).</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Effets</th><th>Période sensible</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Effets déterministes</strong> (mort cellulaire)</td><td>Dose seuil <span class=\"kw-chiffre\">100-200 mGy</span> ⭐⭐⭐ — pas de répercussions en-dessous</td><td>SNC le + touché : sensibilité <strong>10-27 SA</strong></td></tr>\n          <tr><td>Multiplication neuronale</td><td>10-17 SA : <span class=\"kw-alerte\">diminution sévère du QI (- 30)</span>,<span class=\"kw-chiffre\"> 40 %</span> d'arriération mentale (QI &lt; 25) à partir de <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1000</span> mG</span>y</td><td>Conséquences : microcéphalie, RCIU, cataracte, ↓ QI</td></tr>\n          <tr><td>Migration neuronale</td><td>18-27 SA : diminution du QI moins importante</td><td>Relation dose-effet à partir de <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>500</span> mG</span>y</td></tr>\n          <tr><td><strong>Effets stochastiques</strong> (lésions ADN)</td><td><strong>Pas de dose seuil ❌</strong> · Relation dose-effet ✅ : <span class=\"kw-alerte\">↑ risque leucémie/cancer × 1,4</span> (<span class=\"kw-chiffre\">40 %</span>)</td><td>Risque brut leucémie/cancer enfant :<span class=\"kw-chiffre\"> 0,2-0,3 %</span> →<span class=\"kw-chiffre\"> 0,3-0,4 %</span> après <span class=\"kw-clinique\">irradiation</span> fœtale (reste faible)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Autres organes :</strong> mieux préservés ; à doses très élevées : RCIU, voire décès in utero (curiethérapie utérine pour cancer du col par exemple).</div>","frequence":0,"liens":[{"href":"https://www.irsn.fr/professionnels-sante/faq-grossesse-exposition-rayonnements-ionisants","label":"IRSN — FAQ grossesse & rayonnements ionisants"}]},{"id":"27-46","rang":"A","rubrique":"Prise en charge","titre":"**Irradiation et grossesse : en pratique, ce que l'on peut retenir**","contenu":"<p>Le principe directeur : <strong>un examen radiologique justifié n'est jamais une indication d'IMG</strong>. Le « principe de précaution » historique (inquiéter la femme, proposer l'IMG probabiliste) doit être <strong>définitivement abandonné</strong>.</p>\n      <p><strong>Doses fœtales reçues par examen (mGy, moyenne / max) :</strong></p>\n      <table >\n        <thead><tr><th>Examen</th><th>Dose moy</th><th>Dose max</th><th>À retenir</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">RP</span>, RX crâne, RX rachis dorsal, RX membres</td><td>&lt; 0,01</td><td>&lt; 0,01</td><td>Utérus hors faisceau · rassurer +++</td></tr>\n          <tr><td>RX abdomen</td><td>1,4</td><td>4,2</td><td>—</td></tr>\n          <tr><td>RX rachis lombaire</td><td>1,7</td><td>10</td><td>—</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM</span> thorax</td><td>0,06</td><td>0,96</td><td>Très faible (utérus hors faisceau)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM</span> tête</td><td>0,005</td><td>0,005</td><td>Négligeable</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM</span> abdomen</td><td>8,0</td><td>49</td><td>Utérus dans le faisceau</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM</span> bassin</td><td>25</td><td>79</td><td>Dose la + élevée des examens diagnostiques</td></tr>\n          <tr><td>Lavement baryté</td><td>6,8</td><td>24</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Aucun examen radiologique diagnostique standard ne dépasse <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>100</span> mG</span>y</strong> — la limite déterministe. Seules les <span class=\"kw-clinique\">situations exceptionnelles</span> (scopie prolongée, curiethérapie, <span class=\"kw-ttt\">radiothérapie</span> pelvienne) peuvent y conduire.</div>\n      <p><strong>Principes pratiques (ALARA) :</strong></p>\n      <ul>\n        <li>Demander systématiquement à toute femme en âge de procréer si elle est enceinte avant un examen radiologique</li>\n        <li>Privilégier les <span class=\"kw-imagerie\">examens non irradiants</span> : <strong><span class=\"kw-imagerie\">échographie</span></strong>, <strong><span class=\"kw-imagerie\">IRM</span></strong> sans gadolinium (T1)</li>\n        <li><span class=\"kw-clinique\">Tablier de plomb</span> sur l'abdomen pour limiter la dose à l'utérus</li>\n        <li>Limiter le nombre de clichés et le temps de scopie au strict nécessaire</li>\n        <li><strong>Ne pas contre-indiquer un examen radiographique uniquement pour la <span class=\"kw-ci\">grossesse</span></strong> : balance bénéfice/risque souvent favorable</li>\n        <li><span class=\"kw-ci\">Iode 131 radioactif CI absolue</span> ⚠️ (détruit thyroïde fœtale)</li>\n        <li><span class=\"kw-ci\">Radiothérapie CI</span> (doses très élevées) ; en cas d'exposition involontaire → calcul dose-gonades avec IRSN, avis CPDPN</li>\n      </ul>\n      <p><strong>Médecine du travail :</strong> exposition de l'enfant à naître <strong>&lt; 1 mSv</strong> entre la déclaration et l'accouchement. Femme allaitante : pas de poste à risque de contamination interne.</p>\n      <p><strong>Découverte de <span class=\"kw-ci\">grossesse</span> après examen :</strong> si utérus hors faisceau (crâne, thorax, membres) → rassurer ; si utérus dans le faisceau (UIV, hystéro, <span class=\"kw-imagerie\">TDM</span> pelvien) → en standard, rassurer (dose exceptionnellement &gt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>100</span> mG</span>y) ; si examen inhabituel → avis service compétent (radiologue, IRSN).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 333 — Situations sanitaires exceptionnelles</em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-etio\">VIH</span> — <span class=\"q\">charge <span class=\"kw-etio\">virale</span> <span class=\"kw-chiffre\">≥ 400</span> copies/mL à l'accouchement</span></strong></p><p>Objectif : <span class=\"kw-clinique\">CV indétectable</span> (<span class=\"kw-chiffre\">&lt; 50 copies/mL</span>) avant l'accouchement — <span class=\"kw-chiffre\">TMF de 20 % sans ARV → 0,3–0,6 %</span> avec trithérapie efficace</p><ul><li><span class=\"kw-alerte\">CV ≥ 400 copies/mL</span> (CD4 bas, traitement tardif ou non pris) : <span class=\"kw-ttt\">césarienne programmée</span> + <span class=\"kw-ttt\">perfusion prophylactique de zidovudine (AZT)</span></li><li>Gestes <span class=\"kw-ci\">contre-indiqués</span> en salle de naissance : <span class=\"kw-ci\">pH au scalp</span>, <span class=\"kw-ci\">électrode au scalp</span>, <span class=\"kw-ci\">tocométrie interne</span></li></ul><p><strong><span class=\"kw-def\">Allo-immunisation</span> — <span class=\"q\">anémie fœtale sévère</span></strong></p><p><span class=\"kw-ttt\">Transfusion in utero</span> répétée (sang O− déplasmatisé, lavé, irradié) ou <span class=\"kw-ttt\">exsanguinotransfusion in utero</span> (évite la surcharge volémique)</p><ul><li><span class=\"kw-alerte\">Tracé sinusoïdal</span> au <span class=\"kw-imagerie\">RCF</span> = <span class=\"kw-alerte\">anémie fœtale sévère</span>, <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-alerte\">Anasarque fœtale</span> (Hb &lt; <span class=\"kw-chiffre\">5 g/dL</span>) : épanchements des séreuses, ascite</li></ul><p><strong><span class=\"kw-etio\">Grippe</span> grave chez la femme enceinte</strong></p><p><span class=\"kw-ttt\">Oseltamivir</span> curatif débuté <span class=\"kw-chiffre\">&lt; 48h</span> après les 1ᵉʳˢ signes + <span class=\"kw-ttt\">hospitalisation</span> en cas de <span class=\"kw-alerte\">signes de gravité</span> (précautions gouttelettes <span class=\"kw-chiffre\">7 jours</span>)</p><ul><li><span class=\"kw-alerte\">Signes de gravité</span> : <span class=\"kw-alerte\">atteintes fonctions supérieures</span>, <span class=\"kw-chiffre\">FR &gt; 30</span>, <span class=\"kw-chiffre\">PAS &lt; 90</span>, <span class=\"kw-chiffre\">FC &gt; 120</span></li><li>Risque accru d'<span class=\"kw-alerte\">hospitalisation en réanimation</span> pour atteintes respiratoires graves (notamment aux 2ᵉ et 3ᵉ trimestres)</li></ul>","hospit":"<p><strong>Listériose</strong></p><p><span class=\"kw-ttt\">Antibiothérapie démarrée dès la suspicion</span> (confirmation non requise) : <span class=\"kw-ttt\">amoxicilline</span> puis <span class=\"kw-ttt\">biantibiothérapie parentérale amoxicilline + aminoside ≥ 5 jours</span>, relais per os jusqu'à l'accouchement</p><ul><li>Tableau : <span class=\"kw-clinique\">syndrome pseudo-grippal fébrile</span> + <span class=\"kw-clinique\">perte liquidienne vaginale épaisse/teintée</span> (travail prématuré fébrile)</li><li><span class=\"kw-alerte\">Mortalité néonatale élevée (50–75 %)</span> si non traitée</li></ul><p><strong><span class=\"kw-def\">Allo-immunisation</span> — <span class=\"q\">anémie fœtale documentée</span></strong></p><p>Transfert en <span class=\"kw-ttt\">centre de médecine fœtale</span> / maternité de niveau III</p><ul><li><span class=\"kw-imagerie\">Doppler de l'artère cérébrale moyenne (ACM)</span> : <span class=\"kw-alerte\">Vmax &gt; 1,5 MoM</span> pour l'âge gestationnel = signe d'anémie fœtale → indiquer la <span class=\"kw-ttt\">transfusion in utero</span></li><li>Si <span class=\"kw-chiffre\">&lt; 34 SA</span> : possibilité de <span class=\"kw-ttt\">transfusions fœtales répétées</span> toutes les <span class=\"kw-chiffre\">3 semaines</span> ; si terme raisonnable : <span class=\"kw-ttt\">accouchement prématuré induit</span> (AVB ou césarienne) + <span class=\"kw-ttt\">corticothérapie</span></li></ul><p><strong>Toxoplasmose — <span class=\"q\">séroconversion confirmée</span></strong></p><p><span class=\"kw-bio\">PCR</span> sur amniocentèse réalisée <span class=\"kw-chiffre\">≥ 16–18 SA</span> et <span class=\"kw-chiffre\">4 semaines</span> après la date d'infection maternelle estimée</p><ul><li>Orientation vers <span class=\"kw-def\">CPDPN</span> (Centre Pluridisciplinaire de Diagnostic Prénatal) pour décision de prise en charge</li><li><span class=\"kw-imagerie\">Échographies mensuelles</span> à la recherche de <span class=\"kw-clinique\">dilatation ventriculaire</span>, <span class=\"kw-clinique\">hydrocéphalie</span>, <span class=\"kw-clinique\">calcifications intracrâniennes</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Vmax ACM &gt; 1,5 MoM</span> à l'<span class=\"kw-imagerie\">Doppler de l'artère cérébrale moyenne</span> — signe d'anémie fœtale (allo-immunisation)</li><li><span class=\"kw-alerte\">Tracé sinusoïdal</span> au <span class=\"kw-imagerie\">RCF</span> ou <span class=\"kw-alerte\">anasarque fœtale</span> — anémie très sévère, <span class=\"kw-alerte\">urgence</span> transfusionnelle</li><li><span class=\"kw-alerte\">CV VIH ≥ 400 copies/mL</span> à l'accouchement — <span class=\"kw-def\">TMF</span> élevée, césarienne + <span class=\"kw-ttt\">AZT</span> en perfusion</li><li>Toxoplasmose : <span class=\"kw-imagerie\">PCR amniotique positive</span> + <span class=\"kw-imagerie\">anomalies échographiques</span> — fœtopathie sévère, discuter <span class=\"kw-def\">IMG</span> au CPDPN</li><li><span class=\"kw-etio\">Cocaïne</span> en cours de <span class=\"kw-ci\">grossesse</span> → <span class=\"kw-alerte\">hématome rétroplacentaire (HRP)</span> dans les suites immédiates de la prise (RR 4–5)</li><li><span class=\"kw-etio\">Grippe</span> : <span class=\"kw-alerte\">FR &gt; 30</span>, <span class=\"kw-alerte\">PAS &lt; 90</span>, <span class=\"kw-alerte\">FC &gt; 120</span> — atteinte respiratoire grave, <span class=\"kw-alerte\">hospitalisation</span></li></ul>","principes":"<p>Pour chaque risque fœtal, la PEC repose sur <strong><span class=\"kw-def\">prévention primaire</span> (éviction, vaccination, hygiène), dépistage sérologique adapté, et traitement ciblé</strong> selon le germe ou l'agent en cause.</p><p><strong><span class=\"kw-etio\">VIH</span></strong></p><ul><li>Traitement ARV de toute femme enceinte : <span class=\"kw-ttt\">2 INTI + 1 IP</span> (schéma le plus efficace)</li><li><span class=\"kw-ci\">Éfavirenz contre-indiqué au 1ᵉʳ trimestre</span></li><li>Instauration au plus tard <span class=\"kw-chiffre\">avant fin du 2ᵉ trimestre</span> si CV négative ; dès que possible (<span class=\"kw-chiffre\">avant 26 SA</span>) si CV positive ou séropositivité découverte en cours de <span class=\"kw-ci\">grossesse</span></li><li>Traitement du nouveau-né : <span class=\"kw-ttt\">zidovudine (AZT)</span> per os <span class=\"kw-chiffre\">4 semaines</span> si bilan satisfaisant ; trithérapie si prématurité ou CV élevée</li></ul><p><strong><span class=\"kw-def\">Allo-immunisation anti-D</span> — prévention</strong></p><ul><li>Femme <span class=\"kw-chiffre\">RhD−</span>, <span class=\"kw-bio\">RAI</span> négative, fœtus <span class=\"kw-chiffre\">RhD+</span> : <span class=\"kw-ttt\">Rhophylac 300 µg</span> à <span class=\"kw-chiffre\">28 SA</span> (prophylaxie systématique)</li><li>Prophylaxie ciblée dans les <span class=\"kw-chiffre\">&lt; 72h</span> de tout événement à risque de passage de GR fœtales (métrorragies, amniocentèse, VME…)</li><li><span class=\"kw-bio\">RAI</span> de contrôle : <span class=\"kw-chiffre\">M6</span>, <span class=\"kw-chiffre\">M8</span> et <span class=\"kw-chiffre\">M9</span> chez les femmes <span class=\"kw-chiffre\">RhD−</span></li></ul><p><strong>Toxoplasmose — séroconversion prouvée</strong></p><ul><li><span class=\"kw-bio\">PCR</span> amniotique négative, échographies normales : <span class=\"kw-ttt\">spiramycine</span> maintenue jusqu'à l'accouchement + <span class=\"kw-imagerie\">suivi échographique mensuel</span></li><li><span class=\"kw-bio\">PCR</span> amniotique positive : arrêt spiramycine → <span class=\"kw-ttt\">pyriméthamine + sulfadiazine + acide folinique</span> jusqu'à l'accouchement (traitement parasiticide in utero)</li><li><span class=\"kw-imagerie\">Surveillance NFS hebdomadaire</span> sous pyriméthamine-sulfadiazine (hématotoxicité ; risque de <span class=\"kw-alerte\">syndrome de Lyell</span> maternel)</li></ul><p><strong>Listériose</strong></p><ul><li>Dès la suspicion : <span class=\"kw-ttt\">amoxicilline</span> seule (ou <span class=\"kw-ttt\">érythromycine</span> si <span class=\"kw-ci\">allergie</span>)</li><li>Si confirmée : <span class=\"kw-ttt\">amoxicilline parentérale <span class=\"kw-chiffre\">10 jours</span> + aminoside <span class=\"kw-chiffre\">5 jours</span></span>, puis relais oral <span class=\"kw-ttt\">amoxicilline ≥ 4 semaines</span> jusqu'à l'accouchement</li></ul><p><strong>Médicaments tératogènes / fœtotoxiques</strong></p><ul><li>Consultation <span class=\"kw-def\">préconceptionnelle</span> obligatoire pour toute pathologie chronique (adapter le traitement avant <span class=\"kw-ci\">grossesse</span>)</li><li>Référence : <span class=\"kw-def\">CRAT</span> (Centre de Référence sur les Agents Tératogènes) pour évaluation du risque</li><li><span class=\"kw-ci\">AINS contre-indiqués à partir de 24 SA</span> (fermeture prématurée du canal artériel, <span class=\"kw-alerte\">HTAP fœtale</span>, oligo-amnios)</li><li><span class=\"kw-ci\">IEC/sartans contre-indiqués aux 2ᵉ et 3ᵉ trimestres</span> (atteinte rénale fœtale)</li></ul><p><strong><span class=\"kw-clinique\">Irradiation</span></strong></p><ul><li>Privilégier les <span class=\"kw-imagerie\">examens non irradiants</span> (<span class=\"kw-imagerie\">échographie</span>, <span class=\"kw-imagerie\">IRM</span>) pendant la <span class=\"kw-ci\">grossesse</span></li><li>Examens de radiodiagnostic standard : <span class=\"kw-chiffre\">dose fœtale &lt;&lt; 100 mGy</span> → pas d'effet déterministe (seuil <span class=\"kw-chiffre\">100–200 mGy</span>)</li><li>Si l'utérus est hors du faisceau (thorax, crâne, membres) : <span class=\"kw-ttt\">tablier de plomb</span> suffisant, examen réalisable</li><li><span class=\"kw-ci\">Iode 131 totalement proscrit</span> (détruirait la thyroïde fœtale) ; <span class=\"kw-ci\">radiothérapie contre-indiquée</span></li></ul>","suivi":"<p><strong><span class=\"kw-etio\">VIH</span></strong></p><ul><li><span class=\"kw-bio\">Charge virale VIH</span> + <span class=\"kw-bio\">NFS-plaquettes</span> + <span class=\"kw-bio\">transaminases</span> + <span class=\"kw-bio\">créatininémie</span> : <span class=\"kw-def\">suivi</span> <strong>mensuel</strong></li><li><span class=\"kw-bio\">Lymphocytes CD4</span> : <span class=\"kw-def\">suivi</span> trimestriel</li><li>Nouveau-né : <span class=\"kw-bio\">PCR VIH</span> à la <span class=\"kw-chiffre\">naissance</span>, <span class=\"kw-chiffre\">M1</span>, <span class=\"kw-chiffre\">M3</span>, <span class=\"kw-chiffre\">M6</span> (<span class=\"kw-bio\">sérologies</span> inutilisables — AC maternels présents)</li></ul><p><strong><span class=\"kw-def\">Allo-immunisation</span></strong></p><ul><li>Femme <span class=\"kw-chiffre\">RhD−</span> : <span class=\"kw-bio\">RAI</span> à <span class=\"kw-chiffre\">M6</span>, <span class=\"kw-chiffre\">M8</span>, <span class=\"kw-chiffre\">M9</span></li><li>Si <span class=\"kw-bio\">RAI</span> positive et fœtus <span class=\"kw-ttt\">RhD</span>+ : <span class=\"kw-imagerie\">Doppler ACM</span> tous les <span class=\"kw-chiffre\">15 jours</span> (Vmax — seuil d'alerte <span class=\"kw-chiffre\">&gt; 1,5 MoM</span>)</li><li><span class=\"kw-imagerie\">Titrage des AC</span> + <span class=\"kw-bio\">dosage pondéral</span> répétés régulièrement pour dépister une réactivation brutale</li></ul><p><strong>Toxoplasmose (femme non immune)</strong></p><ul><li><span class=\"kw-bio\">Sérologie toxoplasmose mensuelle (IgM + IgG)</span> obligatoire tout au long de la <span class=\"kw-ci\">grossesse</span> chez la femme séronégative</li><li>Si séroconversion : spiramycine précoce + orientation CPDPN + <span class=\"kw-imagerie\">échographies mensuelles</span> (puis bimensuelles si <span class=\"kw-bio\">PCR</span>+ )</li><li>Après la naissance (même si <span class=\"kw-bio\">PCR</span> négative) : <span class=\"kw-imagerie\">fond d'œil</span> + <span class=\"kw-imagerie\">échographie transfontanellaire</span> + <span class=\"kw-def\">suivi</span> sérologique jusqu'à disparition des IgG maternels (<span class=\"kw-chiffre\">4–6 mois</span>)</li></ul>"},"liensGlobaux":[{"href":"https://www.irsn.fr/professionnels-sante/faq-grossesse-exposition-rayonnements-ionisants","label":"irsn.fr"},{"href":"https://www.lecrat.fr","label":"lecrat.fr"}],"cards":[]};